export const MIGRATIONS: { name: string; sql: string }[] = [{"name":"20261028000001_core_schema.sql","sql":"-- PROJECT GOLD (仮称) — コアスキーマ\n-- 方針:\n--  * ランク・利用額・報酬・支払い状態・管理者権限はすべてサーバー側（このDB内の関数）で確定する。\n--  * クライアントは原則 RPC（public.* の security definer 関数）経由で書き込む。テーブルへの直接\n--    INSERT/UPDATE/DELETE 権限は authenticated に付与しない（20261028000005_rls.sql 参照）。\n--  * 店舗予約・指名・ボトル注文はフェーズ2。bookings.kind / venue_references で拡張余地のみ確保。\n\ncreate schema if not exists extensions;\n-- (browser demo) extension skipped\n-- (browser demo) extension skipped\n\n-- ---------------------------------------------------------------- enums\ncreate type public.user_role as enum ('woman', 'man', 'admin');\ncreate type public.account_status as enum ('active', 'suspended', 'deletion_requested', 'deleted');\ncreate type public.verification_status as enum ('unsubmitted', 'pending', 'approved', 'rejected');\ncreate type public.accept_mode as enum ('select', 'open'); -- select=自分で選ぶ / open=幅広く受け付ける\ncreate type public.booking_status as enum ('requested', 'accepted', 'declined', 'canceled', 'completed', 'disputed');\ncreate type public.application_status as enum ('pending', 'approved', 'rejected', 'withdrawn');\ncreate type public.payment_status as enum ('pending', 'authorized', 'captured', 'voided', 'refunded', 'failed');\ncreate type public.payment_kind as enum ('subscription', 'booking', 'adjustment');\ncreate type public.report_status as enum ('open', 'reviewing', 'actioned', 'dismissed');\n\n-- ---------------------------------------------------------------- settings\ncreate table public.app_settings (\n  key text primary key,\n  value jsonb not null,\n  description text not null default '',\n  is_public boolean not null default false, -- true: 一般ユーザーも参照可（料金表示・サービス名など）\n  updated_at timestamptz not null default now(),\n  updated_by uuid\n);\n\n-- ---------------------------------------------------------------- profiles\ncreate table public.profiles (\n  id uuid primary key references auth.users (id) on delete cascade,\n  role public.user_role not null,\n  display_name text not null default '',\n  area text not null default '',\n  status public.account_status not null default 'active',\n  status_reason text,\n  last_seen_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint display_name_len check (char_length(display_name) <= 30)\n);\n\ncreate table public.women_profiles (\n  user_id uuid primary key references public.profiles (id) on delete cascade,\n  headline text not null default '',\n  bio text not null default '',\n  areas text[] not null default '{}',\n  plan_types text[] not null default '{食事,カフェ}',\n  accept_mode public.accept_mode not null default 'select',\n  accept_requests boolean not null default true,\n  min_man_level int not null default 1,\n  ng_note text not null default '',          -- 本人と運営のみ参照\n  is_published boolean not null default false,\n  review_score int not null default 50,       -- 運営の非公開キュレーション(0-100)。本人にも非公開\n  review_note text not null default '',       -- 運営メモ（非公開）\n  rank_code text not null default 'C',\n  rank_score numeric(6,2) not null default 0,\n  xp int not null default 0,\n  level int not null default 1,\n  updated_at timestamptz not null default now(),\n  constraint bio_len check (char_length(bio) <= 1000),\n  constraint headline_len check (char_length(headline) <= 60),\n  constraint review_score_range check (review_score between 0 and 100)\n);\n\ncreate table public.men_profiles (\n  user_id uuid primary key references public.profiles (id) on delete cascade,\n  bio text not null default '',\n  spend_total int not null default 0,          -- 確定済み利用額（返金控除後）。相手方へは非公開\n  spend_rank_code text not null default 'C',\n  xp int not null default 0,\n  level int not null default 1,\n  updated_at timestamptz not null default now(),\n  constraint men_bio_len check (char_length(bio) <= 500)\n);\n\n-- 所属店舗（任意）。公開は is_public かつ運営確認済みの場合のみ。売上額は扱わない。\ncreate table public.venue_references (\n  id uuid primary key default gen_random_uuid(),\n  woman_id uuid not null references public.profiles (id) on delete cascade,\n  venue_name text not null,\n  area text not null default '',\n  is_public boolean not null default false,\n  verify_status public.verification_status not null default 'pending',\n  verified_by uuid references public.profiles (id),\n  verified_at timestamptz,\n  created_at timestamptz not null default now(),\n  constraint venue_name_len check (char_length(venue_name) between 1 and 60)\n);\ncreate unique index venue_one_per_woman on public.venue_references (woman_id);\n\ncreate table public.profile_photos (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.profiles (id) on delete cascade,\n  storage_path text not null,\n  sort_order int not null default 0,\n  status text not null default 'approved' check (status in ('pending', 'approved', 'rejected')),\n  created_at timestamptz not null default now()\n);\ncreate index profile_photos_user on public.profile_photos (user_id, sort_order);\n\ncreate table public.verification_states (\n  user_id uuid primary key references public.profiles (id) on delete cascade,\n  status public.verification_status not null default 'unsubmitted',\n  method text not null default 'none',        -- demo / provider:<name>。本人確認書類そのものは保存しない\n  birth_year int,                              -- 年齢判定に必要な最小情報のみ\n  submitted_at timestamptz,\n  reviewed_at timestamptz,\n  reviewed_by uuid references public.profiles (id),\n  rejection_reason text\n);\n\n-- ---------------------------------------------------------------- availability / plans\ncreate table public.availability_slots (\n  id uuid primary key default gen_random_uuid(),\n  woman_id uuid not null references public.profiles (id) on delete cascade,\n  start_at timestamptz not null,\n  end_at timestamptz not null,\n  area text not null default '',\n  plan_type text not null default '食事',\n  price int not null,\n  note text not null default '',\n  status text not null default 'open' check (status in ('open', 'booked', 'closed')),\n  created_at timestamptz not null default now(),\n  constraint slot_time check (end_at > start_at and end_at - start_at <= interval '8 hours'),\n  constraint slot_price check (price between 0 and 1000000)\n);\ncreate index slots_woman_time on public.availability_slots (woman_id, start_at);\n\ncreate table public.membership_plans (\n  code text primary key,\n  name text not null,\n  monthly_price int not null check (monthly_price >= 0),\n  unlock_rank text not null,\n  perks jsonb not null default '[]',\n  sort int not null default 0,\n  is_active boolean not null default true,\n  is_demo_price boolean not null default true, -- 正式価格未確定のデモ値\n  updated_at timestamptz not null default now()\n);\n\ncreate table public.membership_entitlements (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.profiles (id) on delete cascade,\n  plan_code text not null references public.membership_plans (code),\n  status text not null default 'active' check (status in ('active', 'canceled', 'expired')),\n  started_at timestamptz not null default now(),\n  current_period_end timestamptz not null,\n  cancel_at_period_end boolean not null default false,\n  source text not null default 'sandbox',      -- sandbox / app_store / google_play / stripe\n  external_ref text,\n  updated_at timestamptz not null default now()\n);\ncreate unique index one_active_entitlement on public.membership_entitlements (user_id) where status = 'active';\n\ncreate table public.rank_rules (\n  audience text not null check (audience in ('woman', 'man_spend')),\n  code text not null,\n  label text not null,\n  min_value numeric not null,     -- woman: スコア下限 / man_spend: 確定利用額(円)下限\n  sort int not null,              -- 大きいほど上位\n  primary key (audience, code)\n);\n\ncreate table public.rank_snapshots (\n  id bigint generated always as identity primary key,\n  user_id uuid not null references public.profiles (id) on delete cascade,\n  audience text not null,\n  rank_code text not null,\n  score numeric not null,\n  breakdown jsonb not null,\n  reason text not null default '',\n  computed_at timestamptz not null default now()\n);\ncreate index rank_snapshots_user on public.rank_snapshots (user_id, computed_at desc);\n\n-- ---------------------------------------------------------------- matching\ncreate table public.applications (\n  id uuid primary key default gen_random_uuid(),\n  man_id uuid not null references public.profiles (id) on delete cascade,\n  woman_id uuid not null references public.profiles (id) on delete cascade,\n  message text not null default '',\n  status public.application_status not null default 'pending',\n  source text not null default 'request' check (source in ('request', 'invite')),\n  created_at timestamptz not null default now(),\n  decided_at timestamptz,\n  unique (man_id, woman_id)\n);\n\ncreate table public.bookings (\n  id uuid primary key default gen_random_uuid(),\n  kind text not null default 'companionship', -- フェーズ2: 'venue_visit' 等を追加予定\n  man_id uuid not null references public.profiles (id),\n  woman_id uuid not null references public.profiles (id),\n  slot_id uuid references public.availability_slots (id) on delete set null,\n  start_at timestamptz not null,\n  end_at timestamptz not null,\n  area text not null default '',\n  plan_type text not null default '',\n  price int not null,\n  man_message text not null default '',\n  status public.booking_status not null default 'requested',\n  decline_reason text,\n  cancel_reason text,\n  canceled_by uuid,\n  accepted_at timestamptz,\n  completed_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint booking_time check (end_at > start_at)\n);\ncreate index bookings_woman on public.bookings (woman_id, status, start_at);\ncreate index bookings_man on public.bookings (man_id, status, start_at);\n-- ダブルブッキングの最終防衛線（RPC 内でもロック＋重複チェックを行う）\n-- (browser demo) exclusion constraint skipped\n-- (browser demo) exclusion constraint skipped\n\ncreate table public.booking_events (\n  id bigint generated always as identity primary key,\n  booking_id uuid not null references public.bookings (id) on delete cascade,\n  from_status public.booking_status,\n  to_status public.booking_status not null,\n  actor_id uuid,\n  note text not null default '',\n  created_at timestamptz not null default now()\n);\n\ncreate table public.conversations (\n  id uuid primary key default gen_random_uuid(),\n  man_id uuid not null references public.profiles (id) on delete cascade,\n  woman_id uuid not null references public.profiles (id) on delete cascade,\n  created_at timestamptz not null default now(),\n  last_message_at timestamptz,\n  unique (man_id, woman_id)\n);\n\ncreate table public.messages (\n  id bigint generated always as identity primary key,\n  conversation_id uuid not null references public.conversations (id) on delete cascade,\n  sender_id uuid not null references public.profiles (id) on delete cascade,\n  body text not null,\n  created_at timestamptz not null default now(),\n  constraint body_len check (char_length(body) between 1 and 2000)\n);\ncreate index messages_conv on public.messages (conversation_id, id);\n\ncreate table public.conversation_reads (\n  conversation_id uuid not null references public.conversations (id) on delete cascade,\n  user_id uuid not null references public.profiles (id) on delete cascade,\n  last_read_id bigint not null default 0,\n  primary key (conversation_id, user_id)\n);\n\n-- ---------------------------------------------------------------- money (sandbox until approved)\ncreate table public.payments (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.profiles (id),\n  kind public.payment_kind not null,\n  booking_id uuid references public.bookings (id),\n  plan_code text references public.membership_plans (code),\n  amount int not null check (amount >= 0),\n  currency text not null default 'JPY',\n  status public.payment_status not null default 'pending',\n  provider text not null default 'sandbox',\n  provider_ref text,\n  is_sandbox boolean not null default true,\n  note text not null default '',\n  captured_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index payments_user on public.payments (user_id, created_at desc);\ncreate unique index one_booking_payment on public.payments (booking_id) where kind = 'booking';\n\n-- 女性への支払管理は台帳まで。実送金は契約・法令確認後に実装（entry_type='payout' は予約語）。\ncreate table public.earnings_ledger (\n  id bigint generated always as identity primary key,\n  woman_id uuid not null references public.profiles (id),\n  booking_id uuid references public.bookings (id),\n  payment_id uuid references public.payments (id),\n  entry_type text not null check (entry_type in ('earning', 'reversal', 'payout')),\n  gross int not null,\n  fee int not null,\n  net int not null,\n  is_sandbox boolean not null default true,\n  created_at timestamptz not null default now()\n);\ncreate index earnings_woman on public.earnings_ledger (woman_id, created_at desc);\n\ncreate table public.refunds (\n  id uuid primary key default gen_random_uuid(),\n  payment_id uuid not null references public.payments (id),\n  booking_id uuid references public.bookings (id),\n  amount int not null check (amount > 0),\n  reason text not null default '',\n  status text not null default 'requested' check (status in ('requested', 'approved', 'rejected', 'processed')),\n  requested_by uuid references public.profiles (id),\n  decided_by uuid references public.profiles (id),\n  decided_at timestamptz,\n  created_at timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------- safety\ncreate table public.reports (\n  id uuid primary key default gen_random_uuid(),\n  reporter_id uuid not null references public.profiles (id),\n  target_user_id uuid not null references public.profiles (id),\n  booking_id uuid references public.bookings (id),\n  message_id bigint references public.messages (id) on delete set null,\n  category text not null,\n  detail text not null default '',\n  status public.report_status not null default 'open',\n  admin_note text not null default '',\n  resolved_by uuid references public.profiles (id),\n  resolved_at timestamptz,\n  created_at timestamptz not null default now()\n);\n\ncreate table public.blocks (\n  blocker_id uuid not null references public.profiles (id) on delete cascade,\n  blocked_id uuid not null references public.profiles (id) on delete cascade,\n  created_at timestamptz not null default now(),\n  primary key (blocker_id, blocked_id),\n  check (blocker_id <> blocked_id)\n);\n\ncreate table public.inquiries (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references public.profiles (id) on delete cascade,\n  category text not null check (category in ('general', 'appeal', 'payment', 'safety', 'deletion')),\n  body text not null,\n  status text not null default 'open' check (status in ('open', 'answered', 'closed')),\n  admin_reply text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table public.audit_events (\n  id bigint generated always as identity primary key,\n  actor_id uuid,\n  action text not null,\n  target_type text not null default '',\n  target_id text not null default '',\n  detail jsonb not null default '{}',\n  created_at timestamptz not null default now()\n);\ncreate index audit_created on public.audit_events (created_at desc);\n\ncreate table public.notifications (\n  id bigint generated always as identity primary key,\n  user_id uuid not null references public.profiles (id) on delete cascade,\n  kind text not null,\n  title text not null,\n  body text not null default '',\n  link text,\n  read_at timestamptz,\n  created_at timestamptz not null default now()\n);\ncreate index notifications_user on public.notifications (user_id, id desc);\n\ncreate table public.share_links (\n  id uuid primary key default gen_random_uuid(),\n  woman_id uuid not null references public.profiles (id) on delete cascade,\n  code text not null unique,\n  is_active boolean not null default true,\n  uses int not null default 0,\n  created_at timestamptz not null default now()\n);\ncreate unique index one_active_share_link on public.share_links (woman_id) where is_active;\n"},{"name":"20261028000002_core_functions.sql","sql":"-- 共通ヘルパー、サインアップ時のプロフィール作成、ランク・レベル計算（サーバー確定）\n\n-- ---------------------------------------------------------------- default settings (仮設定)\ninsert into public.app_settings (key, value, description, is_public) values\n  ('service_name', '\"PROJECT GOLD\"', 'サービス名（仮称）', true),\n  ('payment_mode', '\"sandbox\"', 'sandbox=疑似決済のみ / live=承認済み決済事業者（未設定のため起動不可）', true),\n  ('platform_fee_rate', '0.2', '予約金額に対するプラットフォーム手数料率（仮）', false),\n  ('min_age', '20', '登録可能な最低年齢（法令確認待ちの仮設定）', true),\n  ('demo_auto_verify', 'false', 'true の場合デモ本人確認を即時承認（開発環境専用）', false),\n  ('photo_auto_approve', 'true', 'true の場合アップロード写真を即時公開（false で運営審査）', false),\n  ('demo_mode', 'true', 'デモ環境フラグ。予約開始前の完了操作などテスト用の緩和を許可', true),\n  ('count_subscription_toward_spend', 'false', 'サブスク支払を累計利用額に含めるか', false),\n  ('cancellation_policy', '{\"free_until_hours\": 24, \"late_fee_rate\": 0, \"note\": \"仮設定：本番前に確定\"}', 'キャンセル規定（仮）', true),\n  ('dispute_window_days', '7', '完了後に申立てできる日数', true),\n  ('woman_rank_weights', '{\"profile\":15,\"review\":35,\"venue\":10,\"earnings\":20,\"earnings_cap\":300000,\"record\":20,\"record_cap\":20,\"report_penalty\":10}', '女性ランクスコアの配点（監査可能）', false),\n  ('prohibited_terms', '[\"本番\",\"円光\",\"エンコー\",\"援交\",\"援助交際\",\"大人の関係\",\"大人あり\",\"ホ別\",\"性行為\",\"セックス\",\"裏オプ\",\"風俗求人\",\"高収入求人\",\"スカウト報酬\",\"パパ活\"]', '投稿禁止語（性的サービス・求人勧誘の防止）', false),\n  ('price_display_note', '\"表示価格はすべてデモ用の仮設定です\"', '料金表示の注記', true)\non conflict (key) do nothing;\n\ninsert into public.rank_rules (audience, code, label, min_value, sort) values\n  ('woman', 'C', 'C', 0, 1), ('woman', 'B', 'B', 40, 2), ('woman', 'A', 'A', 60, 3), ('woman', 'S', 'S', 80, 4),\n  ('man_spend', 'C', 'C', 0, 1), ('man_spend', 'B', 'B', 50000, 2), ('man_spend', 'A', 'A', 200000, 3), ('man_spend', 'S', 'S', 500000, 4)\non conflict do nothing;\n\ninsert into public.membership_plans (code, name, monthly_price, unlock_rank, perks, sort) values\n  ('FREE', 'FREE', 0, 'C', '[\"Cランクの女性へ申し込み\",\"チャット・予約管理\"]', 1),\n  ('SILVER', 'SILVER', 4980, 'B', '[\"Bランクまで申し込み可能\",\"検索条件の保存\"]', 2),\n  ('GOLD', 'GOLD', 14800, 'A', '[\"Aランクまで申し込み可能\",\"優先サポート\"]', 3),\n  ('BLACK', 'BLACK', 29800, 'S', '[\"全ランクへ申し込み可能\",\"専任コンシェルジュ（予定）\"]', 4)\non conflict do nothing;\n\n-- ---------------------------------------------------------------- tiny helpers\ncreate or replace function public.setting(p_key text) returns jsonb\nlanguage sql stable security definer set search_path = public as $$\n  select value from public.app_settings where key = p_key\n$$;\n\ncreate or replace function public.setting_num(p_key text, p_default numeric) returns numeric\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce((select (value #>> '{}')::numeric from public.app_settings where key = p_key), p_default)\n$$;\n\ncreate or replace function public.setting_bool(p_key text) returns boolean\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce((select (value #>> '{}')::boolean from public.app_settings where key = p_key), false)\n$$;\n\ncreate or replace function public.is_admin() returns boolean\nlanguage sql stable security definer set search_path = public as $$\n  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin' and status = 'active')\n$$;\n\ncreate or replace function public.my_role() returns public.user_role\nlanguage sql stable security definer set search_path = public as $$\n  select role from public.profiles where id = auth.uid()\n$$;\n\ncreate or replace function public.rank_sort(p_audience text, p_code text) returns int\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce((select sort from public.rank_rules where audience = p_audience and code = p_code), 0)\n$$;\n\ncreate or replace function public.rank_for_value(p_audience text, p_value numeric) returns text\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce(\n    (select code from public.rank_rules where audience = p_audience and min_value <= p_value order by sort desc limit 1),\n    (select code from public.rank_rules where audience = p_audience order by sort asc limit 1))\n$$;\n\ncreate or replace function public.is_blocked_pair(a uuid, b uuid) returns boolean\nlanguage sql stable security definer set search_path = public as $$\n  select exists (select 1 from public.blocks where (blocker_id = a and blocked_id = b) or (blocker_id = b and blocked_id = a))\n$$;\n\ncreate or replace function public.level_for_xp(p_xp int) returns int\nlanguage sql immutable as $$ select floor(sqrt(greatest(p_xp, 0) / 100.0))::int + 1 $$;\n\ncreate or replace function public.xp_for_level(p_level int) returns int\nlanguage sql immutable as $$ select (100 * (p_level - 1) * (p_level - 1))::int $$;\n\ncreate or replace function public.raise_app(p_code text, p_message text) returns void\nlanguage plpgsql as $$\nbegin\n  raise exception using errcode = 'P0001', message = p_message, hint = p_code;\nend $$;\n\ncreate or replace function public.require_user() returns uuid\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare v uuid := auth.uid(); s public.account_status;\nbegin\n  if v is null then perform public.raise_app('AUTH_REQUIRED', 'ログインが必要です'); end if;\n  select status into s from public.profiles where id = v;\n  if s is null then perform public.raise_app('AUTH_REQUIRED', 'プロフィールが見つかりません'); end if;\n  if s <> 'active' then perform public.raise_app('ACCOUNT_INACTIVE', 'このアカウントは現在利用できません'); end if;\n  return v;\nend $$;\n\ncreate or replace function public.require_role(p_role public.user_role) returns uuid\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare v uuid := public.require_user();\nbegin\n  if (select role from public.profiles where id = v) <> p_role then\n    perform public.raise_app('FORBIDDEN', 'この操作は許可されていません');\n  end if;\n  return v;\nend $$;\n\ncreate or replace function public.require_admin() returns uuid\nlanguage plpgsql stable security definer set search_path = public as $$\nbegin\n  if not public.is_admin() then perform public.raise_app('FORBIDDEN', '管理者権限が必要です'); end if;\n  return auth.uid();\nend $$;\n\ncreate or replace function public.audit(p_action text, p_target_type text, p_target_id text, p_detail jsonb default '{}')\nreturns void language sql security definer set search_path = public as $$\n  insert into public.audit_events (actor_id, action, target_type, target_id, detail)\n  values (auth.uid(), p_action, p_target_type, p_target_id, coalesce(p_detail, '{}'))\n$$;\n\ncreate or replace function public.notify(p_user uuid, p_kind text, p_title text, p_body text, p_link text default null)\nreturns void language sql security definer set search_path = public as $$\n  insert into public.notifications (user_id, kind, title, body, link) values (p_user, p_kind, p_title, p_body, p_link)\n$$;\n\n-- 性的サービスの売買・求人勧誘につながる文言をサーバー側で拒否する\ncreate or replace function public.assert_clean_text(p_text text) returns void\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare term text; t text := lower(coalesce(p_text, ''));\nbegin\n  for term in select jsonb_array_elements_text(coalesce(public.setting('prohibited_terms'), '[]')) loop\n    if position(lower(term) in t) > 0 then\n      perform public.raise_app('MODERATION_BLOCKED',\n        '利用規約で禁止されている内容が含まれているため送信できません（性的サービスの売買・求人勧誘などは禁止されています）');\n    end if;\n  end loop;\nend $$;\n\n-- ---------------------------------------------------------------- signup hook\ncreate or replace function public.handle_new_user() returns trigger\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  v_role text := coalesce(new.raw_user_meta_data ->> 'role', '');\n  v_name text := left(coalesce(nullif(new.raw_user_meta_data ->> 'display_name', ''), split_part(new.email, '@', 1)), 30);\nbegin\n  -- 管理者ロールはクライアントから指定不可（運営が SQL で付与する）\n  if v_role not in ('woman', 'man') then\n    raise exception 'invalid role' using errcode = '22023';\n  end if;\n  insert into public.profiles (id, role, display_name) values (new.id, v_role::public.user_role, v_name);\n  if v_role = 'woman' then\n    insert into public.women_profiles (user_id) values (new.id);\n  else\n    insert into public.men_profiles (user_id) values (new.id);\n  end if;\n  insert into public.verification_states (user_id) values (new.id);\n  insert into public.notifications (user_id, kind, title, body, link) values\n    (new.id, 'system', 'ようこそ', '本人確認（20歳以上）を完了すると、申し込み・予約機能を利用できます。', '/verification');\n  return new;\nend $$;\n\ncreate trigger on_auth_user_created after insert on auth.users\n  for each row execute function public.handle_new_user();\n\n-- ---------------------------------------------------------------- stats & ranks (server authoritative)\ncreate or replace function public.woman_earnings_net(p_woman uuid) returns int\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce(sum(net), 0)::int from public.earnings_ledger\n  where woman_id = p_woman and entry_type in ('earning', 'reversal')\n    and is_sandbox = (public.setting('payment_mode') #>> '{}' = 'sandbox')\n$$;\n\ncreate or replace function public.man_spend_total(p_man uuid) returns int\nlanguage sql stable security definer set search_path = public as $$\n  with mode as (select (public.setting('payment_mode') #>> '{}' = 'sandbox') as sb)\n  select (\n    coalesce((select sum(p.amount) from public.payments p, mode\n      where p.user_id = p_man and p.is_sandbox = mode.sb and p.status in ('captured', 'refunded')\n        and (p.kind in ('booking', 'adjustment')\n             or (p.kind = 'subscription' and public.setting_bool('count_subscription_toward_spend')))), 0)\n    - coalesce((select sum(r.amount) from public.refunds r join public.payments p on p.id = r.payment_id, mode\n      where p.user_id = p_man and p.is_sandbox = mode.sb and r.status = 'processed'\n        and (p.kind in ('booking', 'adjustment')\n             or (p.kind = 'subscription' and public.setting_bool('count_subscription_toward_spend')))), 0)\n  )::int\n$$;\n\ncreate or replace function public.completed_count(p_user uuid) returns int\nlanguage sql stable security definer set search_path = public as $$\n  select count(*)::int from public.bookings where (man_id = p_user or woman_id = p_user) and status = 'completed'\n$$;\n\ncreate or replace function public.actioned_reports(p_user uuid) returns int\nlanguage sql stable security definer set search_path = public as $$\n  select count(*)::int from public.reports where target_user_id = p_user and status = 'actioned'\n$$;\n\ncreate or replace function public.recompute_woman(p_woman uuid, p_reason text default '') returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  w public.women_profiles; wt jsonb := public.setting('woman_rank_weights');\n  n_photos int; venue_ok boolean; net int; done int; bad int; verified boolean;\n  s_profile numeric; s_review numeric; s_venue numeric; s_earn numeric; s_record numeric; s_pen numeric; total numeric;\n  v_rank text; v_xp int;\nbegin\n  select * into w from public.women_profiles where user_id = p_woman;\n  if not found then return; end if;\n  select count(*) into n_photos from public.profile_photos where user_id = p_woman and status = 'approved';\n  select exists (select 1 from public.venue_references where woman_id = p_woman and verify_status = 'approved') into venue_ok;\n  net := public.woman_earnings_net(p_woman);\n  done := public.completed_count(p_woman);\n  bad := public.actioned_reports(p_woman);\n  select status = 'approved' into verified from public.verification_states where user_id = p_woman;\n\n  s_profile := round((case when char_length(w.bio) >= 30 then 0.35 else 0 end\n             + case when n_photos >= 3 then 0.35 when n_photos >= 1 then 0.15 else 0 end\n             + case when cardinality(w.areas) > 0 then 0.2 else 0 end\n             + case when char_length(w.headline) > 0 then 0.1 else 0 end) * (wt ->> 'profile')::numeric, 2);\n  s_review := round(w.review_score / 100.0 * (wt ->> 'review')::numeric, 2);\n  s_venue := case when venue_ok then (wt ->> 'venue')::numeric else 0 end;\n  s_earn := round(least(net::numeric / greatest((wt ->> 'earnings_cap')::numeric, 1), 1) * (wt ->> 'earnings')::numeric, 2);\n  s_record := round(least(done::numeric / greatest((wt ->> 'record_cap')::numeric, 1), 1) * (wt ->> 'record')::numeric, 2);\n  s_pen := bad * (wt ->> 'report_penalty')::numeric;\n  total := greatest(s_profile + s_review + s_venue + s_earn + s_record - s_pen, 0);\n  v_rank := public.rank_for_value('woman', total);\n\n  v_xp := (case when verified then 200 else 0 end) + done * 100 + (case when n_photos >= 3 then 100 else 0 end)\n          + least(net / 1000, 3000);\n  v_xp := greatest(v_xp - bad * 200, 0);\n\n  update public.women_profiles set rank_code = v_rank, rank_score = total, xp = v_xp,\n    level = public.level_for_xp(v_xp), updated_at = now() where user_id = p_woman;\n\n  if w.rank_code is distinct from v_rank or w.rank_score is distinct from total then\n    insert into public.rank_snapshots (user_id, audience, rank_code, score, breakdown, reason)\n    values (p_woman, 'woman', v_rank, total, jsonb_build_object(\n      'profile', s_profile, 'review', s_review, 'venue', s_venue, 'earnings', s_earn, 'record', s_record,\n      'penalty', s_pen, 'inputs', jsonb_build_object('photos', n_photos, 'venue_verified', venue_ok,\n      'net_earnings', net, 'completed', done, 'actioned_reports', bad), 'weights', wt), p_reason);\n  end if;\nend $$;\n\ncreate or replace function public.recompute_man(p_man uuid, p_reason text default '') returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare m public.men_profiles; spend int; done int; bad int; verified boolean; v_rank text; v_xp int;\nbegin\n  select * into m from public.men_profiles where user_id = p_man;\n  if not found then return; end if;\n  spend := public.man_spend_total(p_man);\n  done := public.completed_count(p_man);\n  bad := public.actioned_reports(p_man);\n  select status = 'approved' into verified from public.verification_states where user_id = p_man;\n  v_rank := public.rank_for_value('man_spend', spend);\n  v_xp := (case when verified then 200 else 0 end) + done * 100 + least(spend / 1000, 3000)\n          + (case when char_length(m.bio) >= 20 then 50 else 0 end);\n  v_xp := greatest(v_xp - bad * 200, 0);\n  update public.men_profiles set spend_total = spend, spend_rank_code = v_rank, xp = v_xp,\n    level = public.level_for_xp(v_xp), updated_at = now() where user_id = p_man;\n  if m.spend_rank_code is distinct from v_rank or m.spend_total is distinct from spend then\n    insert into public.rank_snapshots (user_id, audience, rank_code, score, breakdown, reason)\n    values (p_man, 'man_spend', v_rank, spend, jsonb_build_object('spend_total', spend, 'completed', done,\n      'actioned_reports', bad, 'verified', verified), p_reason);\n  end if;\nend $$;\n\ncreate or replace function public.recompute_user(p_user uuid, p_reason text default '') returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  if (select role from public.profiles where id = p_user) = 'woman' then\n    perform public.recompute_woman(p_user, p_reason);\n  else\n    perform public.recompute_man(p_user, p_reason);\n  end if;\nend $$;\n\n-- 男性の申し込み可能ランク = max(累計確定利用額のランク, 有効な月額プランの解放ランク)\ncreate or replace function public.man_access(p_man uuid) returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare spend_rank text; plan_rank text; plan_code text; v_unlock text; verified boolean;\nbegin\n  select spend_rank_code into spend_rank from public.men_profiles where user_id = p_man;\n  select e.plan_code, p.unlock_rank into plan_code, plan_rank\n    from public.membership_entitlements e join public.membership_plans p on p.code = e.plan_code\n    where e.user_id = p_man and e.status = 'active' and e.current_period_end > now() limit 1;\n  if plan_code is null then\n    select code, unlock_rank into plan_code, plan_rank from public.membership_plans where code = 'FREE';\n  end if;\n  v_unlock := case when public.rank_sort('woman', coalesce(plan_rank, 'C')) >= public.rank_sort('woman', coalesce(spend_rank, 'C'))\n                   then coalesce(plan_rank, 'C') else spend_rank end;\n  select status = 'approved' into verified from public.verification_states where user_id = p_man;\n  return jsonb_build_object('spend_rank', spend_rank, 'plan_code', plan_code, 'plan_rank', plan_rank,\n    'unlocked_rank', v_unlock, 'unlocked_sort', public.rank_sort('woman', v_unlock), 'verified', coalesce(verified, false),\n    'source', case when public.rank_sort('woman', coalesce(plan_rank,'C')) >= public.rank_sort('woman', coalesce(spend_rank,'C'))\n                   then 'plan' else 'spend' end);\nend $$;\n\n-- 男性→女性への申し込み可否と理由（UI のロック表示もこれを使う）\ncreate or replace function public.eligibility(p_man uuid, p_woman uuid) returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare\n  acc jsonb := public.man_access(p_man); w public.women_profiles; wp public.profiles; mp public.men_profiles;\n  reasons jsonb := '[]'; app public.applications; rank_locked boolean := false; invited boolean; can_apply boolean;\n  w_verified boolean;\nbegin\n  select * into w from public.women_profiles where user_id = p_woman;\n  select * into wp from public.profiles where id = p_woman;\n  select * into mp from public.men_profiles where user_id = p_man;\n  select * into app from public.applications where man_id = p_man and woman_id = p_woman;\n  select status = 'approved' into w_verified from public.verification_states where user_id = p_woman;\n  invited := app.status = 'approved' and app.source = 'invite';\n\n  if wp.id is null or wp.status <> 'active' or not w.is_published or not coalesce(w_verified, false) then\n    reasons := reasons || jsonb_build_object('code', 'UNAVAILABLE', 'message', '現在このプロフィールは受付していません');\n  end if;\n  if public.is_blocked_pair(p_man, p_woman) then\n    reasons := reasons || jsonb_build_object('code', 'BLOCKED', 'message', '申し込みできません');\n  end if;\n  if not (acc ->> 'verified')::boolean then\n    reasons := reasons || jsonb_build_object('code', 'VERIFY_REQUIRED', 'message', '本人確認（20歳以上）の完了が必要です');\n  end if;\n  if public.rank_sort('woman', w.rank_code) > (acc ->> 'unlocked_sort')::int and not coalesce(invited, false) then\n    rank_locked := true;\n    reasons := reasons || jsonb_build_object('code', 'RANK_LOCKED', 'message',\n      format('%sランクの女性への申し込みには、%sランクの解放が必要です', w.rank_code, w.rank_code));\n  end if;\n  if coalesce(mp.level, 1) < w.min_man_level and not coalesce(invited, false) then\n    reasons := reasons || jsonb_build_object('code', 'LEVEL_REQUIRED', 'message',\n      format('この方への申し込みには Lv.%s 以上が必要です', w.min_man_level));\n  end if;\n  if not w.accept_requests then\n    reasons := reasons || jsonb_build_object('code', 'PAUSED', 'message', '現在新規の申し込みを停止しています');\n  end if;\n  can_apply := jsonb_array_length(reasons) = 0;\n  if w.accept_mode = 'select' and coalesce(app.status::text, '') <> 'approved' then\n    reasons := reasons || jsonb_build_object('code', 'APPROVAL_REQUIRED', 'message',\n      'この方は「自分で選ぶ」モードです。まずプロフィールへの申請を送り、承認されると予約申請ができます');\n  end if;\n  return jsonb_build_object(\n    'can_request', jsonb_array_length(reasons) = 0,\n    'can_apply', can_apply and w.accept_mode = 'select' and app.id is null,\n    'rank_locked', rank_locked,\n    'application_status', app.status,\n    'application_source', app.source,\n    'reasons', reasons,\n    'access', acc);\nend $$;\n"},{"name":"20261028000003_user_rpc.sql","sql":"-- 一般ユーザー向け RPC。すべて security definer で、関数内で本人・役割・状態を検証する。\n\n-- ---------------------------------------------------------------- builders\ncreate or replace function public.photo_paths(p_user uuid) returns jsonb\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce(jsonb_agg(storage_path order by sort_order, created_at), '[]')\n  from public.profile_photos where user_id = p_user and status = 'approved'\n$$;\n\ncreate or replace function public.public_venue(p_woman uuid) returns jsonb\nlanguage sql stable security definer set search_path = public as $$\n  select jsonb_build_object('name', venue_name, 'area', area) from public.venue_references\n  where woman_id = p_woman and is_public and verify_status = 'approved'\n$$;\n\ncreate or replace function public.woman_card(p_woman uuid, p_viewer uuid) returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare w public.women_profiles; p public.profiles; v_next jsonb; acc jsonb;\nbegin\n  select * into w from public.women_profiles where user_id = p_woman;\n  select * into p from public.profiles where id = p_woman;\n  select jsonb_build_object('start_at', start_at, 'end_at', end_at, 'price', price, 'plan_type', plan_type)\n    into v_next from public.availability_slots\n    where woman_id = p_woman and status = 'open' and start_at > now() order by start_at limit 1;\n  acc := case when p_viewer is not null and public.my_role() = 'man' then public.man_access(p_viewer) end;\n  return jsonb_build_object(\n    'id', p.id, 'display_name', p.display_name, 'headline', w.headline, 'area', p.area, 'areas', to_jsonb(w.areas),\n    'rank_code', w.rank_code, 'level', w.level, 'accept_mode', w.accept_mode, 'accept_requests', w.accept_requests,\n    'plan_types', to_jsonb(w.plan_types), 'photos', public.photo_paths(p_woman), 'venue', public.public_venue(p_woman),\n    'next_slot', v_next,\n    'locked', case when acc is null then false\n                   else public.rank_sort('woman', w.rank_code) > (acc ->> 'unlocked_sort')::int\n                        and not exists (select 1 from public.applications a where a.man_id = p_viewer and a.woman_id = p_woman\n                                        and a.status = 'approved' and a.source = 'invite') end);\nend $$;\n\n-- 女性に見せる男性情報（利用額・支払額は含めない）\ncreate or replace function public.man_summary(p_man uuid) returns jsonb\nlanguage sql stable security definer set search_path = public as $$\n  select jsonb_build_object('id', p.id, 'display_name', p.display_name, 'area', p.area, 'level', m.level,\n    'bio', m.bio, 'verified', coalesce(v.status = 'approved', false), 'completed', public.completed_count(p.id),\n    'photos', public.photo_paths(p.id), 'joined_at', p.created_at)\n  from public.profiles p join public.men_profiles m on m.user_id = p.id\n  left join public.verification_states v on v.user_id = p.id where p.id = p_man\n$$;\n\ncreate or replace function public.badges(p_user uuid) returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare b jsonb := '[]'; done int := public.completed_count(p_user); verified boolean; n_photos int;\nbegin\n  select status = 'approved' into verified from public.verification_states where user_id = p_user;\n  select count(*) into n_photos from public.profile_photos where user_id = p_user and status = 'approved';\n  b := b || jsonb_build_object('code', 'verified', 'label', '本人確認済み', 'earned', coalesce(verified, false));\n  b := b || jsonb_build_object('code', 'first', 'label', 'はじめての予約完了', 'earned', done >= 1);\n  b := b || jsonb_build_object('code', 'five', 'label', '予約完了 5回', 'earned', done >= 5);\n  b := b || jsonb_build_object('code', 'safe', 'label', 'トラブルなし（3回以上完了）', 'earned', done >= 3 and public.actioned_reports(p_user) = 0);\n  if (select role from public.profiles where id = p_user) = 'woman' then\n    b := b || jsonb_build_object('code', 'profile', 'label', '写真3枚以上', 'earned', n_photos >= 3);\n  end if;\n  return b;\nend $$;\n\ncreate or replace function public.ensure_conversation(p_man uuid, p_woman uuid) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v uuid;\nbegin\n  insert into public.conversations (man_id, woman_id) values (p_man, p_woman)\n    on conflict (man_id, woman_id) do nothing;\n  select id into v from public.conversations where man_id = p_man and woman_id = p_woman;\n  return v;\nend $$;\n\ncreate or replace function public.can_chat(p_conversation uuid, p_user uuid) returns boolean\nlanguage sql stable security definer set search_path = public as $$\n  select exists (\n    select 1 from public.conversations c\n    join public.profiles pm on pm.id = c.man_id join public.profiles pw on pw.id = c.woman_id\n    where c.id = p_conversation and p_user in (c.man_id, c.woman_id)\n      and pm.status = 'active' and pw.status = 'active'\n      and not public.is_blocked_pair(c.man_id, c.woman_id)\n      and (exists (select 1 from public.applications a where a.man_id = c.man_id and a.woman_id = c.woman_id and a.status = 'approved')\n        or exists (select 1 from public.bookings b where b.man_id = c.man_id and b.woman_id = c.woman_id\n                   and b.status in ('accepted', 'completed', 'disputed'))))\n$$;\n\n-- ---------------------------------------------------------------- me / settings\ncreate or replace function public.get_public_settings() returns jsonb\nlanguage sql stable security definer set search_path = public as $$\n  select jsonb_build_object(\n    'settings', (select coalesce(jsonb_object_agg(key, value), '{}') from public.app_settings where is_public),\n    'plans', (select coalesce(jsonb_agg(jsonb_build_object('code', code, 'name', name, 'monthly_price', monthly_price,\n              'unlock_rank', unlock_rank, 'perks', perks, 'is_demo_price', is_demo_price) order by sort), '[]')\n              from public.membership_plans where is_active),\n    'rank_rules', (select coalesce(jsonb_agg(jsonb_build_object('audience', audience, 'code', code, 'label', label,\n              'min_value', min_value, 'sort', sort) order by audience, sort), '[]') from public.rank_rules))\n$$;\n\ncreate or replace function public.get_me() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := auth.uid(); p public.profiles; v public.verification_states; r jsonb; w public.women_profiles; m public.men_profiles;\nbegin\n  if uid is null then perform public.raise_app('AUTH_REQUIRED', 'ログインが必要です'); end if;\n  select * into p from public.profiles where id = uid;\n  if not found then perform public.raise_app('AUTH_REQUIRED', 'プロフィールが見つかりません'); end if;\n  update public.profiles set last_seen_at = now() where id = uid;\n  select * into v from public.verification_states where user_id = uid;\n  r := jsonb_build_object(\n    'id', p.id, 'role', p.role, 'display_name', p.display_name, 'area', p.area, 'status', p.status,\n    'status_reason', p.status_reason, 'created_at', p.created_at,\n    'verification', jsonb_build_object('status', coalesce(v.status, 'unsubmitted'), 'method', v.method,\n       'submitted_at', v.submitted_at, 'rejection_reason', v.rejection_reason),\n    'photos', public.photo_paths(uid),\n    'photo_items', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'path', storage_path, 'status', status) order by sort_order, created_at), '[]')\n                    from public.profile_photos where user_id = uid),\n    'unread_notifications', (select count(*) from public.notifications where user_id = uid and read_at is null),\n    'badges', public.badges(uid));\n  if p.role = 'woman' then\n    select * into w from public.women_profiles where user_id = uid;\n    r := r || jsonb_build_object('woman', jsonb_build_object(\n      'headline', w.headline, 'bio', w.bio, 'areas', to_jsonb(w.areas), 'plan_types', to_jsonb(w.plan_types),\n      'accept_mode', w.accept_mode, 'accept_requests', w.accept_requests, 'min_man_level', w.min_man_level,\n      'ng_note', w.ng_note, 'is_published', w.is_published, 'rank_code', w.rank_code, 'rank_score', w.rank_score,\n      'xp', w.xp, 'level', w.level, 'level_floor_xp', public.xp_for_level(w.level), 'next_level_xp', public.xp_for_level(w.level + 1),\n      'venue', (select jsonb_build_object('id', id, 'name', venue_name, 'area', area, 'is_public', is_public, 'verify_status', verify_status)\n                from public.venue_references where woman_id = uid)));\n  elsif p.role = 'man' then\n    select * into m from public.men_profiles where user_id = uid;\n    r := r || jsonb_build_object('man', jsonb_build_object(\n      'bio', m.bio, 'spend_total', m.spend_total, 'spend_rank', m.spend_rank_code, 'xp', m.xp, 'level', m.level,\n      'level_floor_xp', public.xp_for_level(m.level), 'next_level_xp', public.xp_for_level(m.level + 1)),\n      'access', public.man_access(uid),\n      'entitlement', (select jsonb_build_object('plan_code', plan_code, 'status', status, 'current_period_end', current_period_end,\n                      'cancel_at_period_end', cancel_at_period_end, 'source', source)\n                      from public.membership_entitlements where user_id = uid and status = 'active' limit 1));\n  end if;\n  return r;\nend $$;\n\ncreate or replace function public.update_my_profile(p_display_name text, p_area text, p_bio text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user();\nbegin\n  if char_length(trim(coalesce(p_display_name, ''))) = 0 then perform public.raise_app('INVALID', '表示名を入力してください'); end if;\n  perform public.assert_clean_text(p_display_name || ' ' || coalesce(p_bio, ''));\n  update public.profiles set display_name = left(trim(p_display_name), 30), area = left(coalesce(p_area, ''), 30), updated_at = now()\n    where id = uid;\n  if public.my_role() = 'man' then\n    update public.men_profiles set bio = left(coalesce(p_bio, ''), 500), updated_at = now() where user_id = uid;\n  elsif public.my_role() = 'woman' then\n    update public.women_profiles set bio = left(coalesce(p_bio, ''), 1000), updated_at = now() where user_id = uid;\n  end if;\n  perform public.recompute_user(uid, 'profile_updated');\n  return public.get_me();\nend $$;\n\ncreate or replace function public.submit_verification(p_birth_year int, p_consent boolean) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); cur public.verification_status; min_age int := public.setting_num('min_age', 20)::int;\n  auto boolean := public.setting_bool('demo_auto_verify');\nbegin\n  if not coalesce(p_consent, false) then perform public.raise_app('INVALID', '規約への同意が必要です'); end if;\n  if p_birth_year is null or p_birth_year < 1900 then perform public.raise_app('INVALID', '生年を正しく入力してください'); end if;\n  -- 生年のみで判定するため保守的に「満年齢が確実に min_age 以上」の場合のみ受け付ける\n  if extract(year from now() at time zone 'Asia/Tokyo')::int - p_birth_year <= min_age then\n    perform public.raise_app('AGE_RESTRICTED', format('%s歳以上の方のみご利用いただけます', min_age));\n  end if;\n  select status into cur from public.verification_states where user_id = uid;\n  if cur = 'approved' then perform public.raise_app('INVALID', '本人確認は完了しています'); end if;\n  update public.verification_states set status = (case when auto then 'approved' else 'pending' end)::public.verification_status, method = 'demo',\n    birth_year = p_birth_year, submitted_at = now(), reviewed_at = case when auto then now() end, rejection_reason = null\n    where user_id = uid;\n  perform public.audit('verification.submit', 'user', uid::text, jsonb_build_object('auto', auto));\n  perform public.recompute_user(uid, 'verification');\n  return public.get_me();\nend $$;\n\n-- ---------------------------------------------------------------- notifications\ncreate or replace function public.list_notifications(p_limit int default 50) returns jsonb\nlanguage sql security definer set search_path = public as $$\n  select coalesce(jsonb_agg(to_jsonb(n) - 'user_id' order by n.id desc), '[]') from (\n    select * from public.notifications where user_id = auth.uid() order by id desc limit least(coalesce(p_limit, 50), 200)) n\n$$;\n\ncreate or replace function public.mark_notifications_read() returns void\nlanguage sql security definer set search_path = public as $$\n  update public.notifications set read_at = now() where user_id = auth.uid() and read_at is null\n$$;\n\n-- ---------------------------------------------------------------- men: browse\ncreate or replace function public.search_women(p_area text default null, p_rank text default null, p_date date default null,\n  p_open_only boolean default false, p_query text default null, p_limit int default 30, p_offset int default 0) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); r public.user_role := public.my_role();\nbegin\n  if r not in ('man', 'admin') then perform public.raise_app('FORBIDDEN', 'この操作は許可されていません'); end if;\n  return (select coalesce(jsonb_agg(public.woman_card(x.user_id, uid) order by x.has_slot desc, x.next_at nulls last, x.updated_at desc), '[]')\n    from (\n      select w.user_id, w.updated_at,\n        (select min(s.start_at) from public.availability_slots s where s.woman_id = w.user_id and s.status = 'open' and s.start_at > now()) as next_at,\n        exists (select 1 from public.availability_slots s where s.woman_id = w.user_id and s.status = 'open' and s.start_at > now()) as has_slot\n      from public.women_profiles w\n      join public.profiles p on p.id = w.user_id\n      join public.verification_states v on v.user_id = w.user_id and v.status = 'approved'\n      where w.is_published and p.status = 'active'\n        and not public.is_blocked_pair(uid, w.user_id)\n        and (p_area is null or p_area = '' or p.area = p_area or p_area = any (w.areas))\n        and (p_rank is null or p_rank = '' or w.rank_code = p_rank)\n        and (not coalesce(p_open_only, false) or (w.accept_requests and w.accept_mode = 'open'))\n        and (p_query is null or p_query = '' or p.display_name ilike '%' || p_query || '%' or w.headline ilike '%' || p_query || '%')\n        and (p_date is null or exists (select 1 from public.availability_slots s where s.woman_id = w.user_id and s.status = 'open'\n             and (s.start_at at time zone 'Asia/Tokyo')::date = p_date))\n      order by has_slot desc, next_at nulls last, w.updated_at desc\n      limit least(coalesce(p_limit, 30), 100) offset greatest(coalesce(p_offset, 0), 0)) x);\nend $$;\n\ncreate or replace function public.get_woman_detail(p_woman uuid) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); r public.user_role := public.my_role(); w public.women_profiles; card jsonb;\nbegin\n  if r not in ('man', 'admin') and uid <> p_woman then perform public.raise_app('FORBIDDEN', 'この操作は許可されていません'); end if;\n  select * into w from public.women_profiles where user_id = p_woman;\n  if not found or (r = 'man' and (public.is_blocked_pair(uid, p_woman) or not w.is_published\n      or (select status from public.profiles where id = p_woman) <> 'active')) then\n    perform public.raise_app('NOT_FOUND', 'プロフィールが見つかりません');\n  end if;\n  card := public.woman_card(p_woman, uid);\n  return card || jsonb_build_object(\n    'bio', w.bio,\n    'slots', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'start_at', s.start_at, 'end_at', s.end_at, 'area', s.area,\n               'plan_type', s.plan_type, 'price', s.price, 'note', s.note,\n               'my_request', (select b.status from public.bookings b where b.slot_id = s.id and b.man_id = uid order by b.created_at desc limit 1))\n               order by s.start_at), '[]')\n              from public.availability_slots s where s.woman_id = p_woman and s.status = 'open' and s.start_at > now()\n                and s.start_at < now() + interval '30 days'),\n    'eligibility', case when r = 'man' then public.eligibility(uid, p_woman) end,\n    'conversation_id', (select c.id from public.conversations c where c.man_id = uid and c.woman_id = p_woman and public.can_chat(c.id, uid)),\n    'badges', (select jsonb_agg(b) from jsonb_array_elements(public.badges(p_woman)) b where (b ->> 'earned')::boolean));\nend $$;\n\n-- ---------------------------------------------------------------- men: membership (sandbox)\ncreate or replace function public.membership_overview() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('man'); m public.men_profiles; nxt record;\nbegin\n  select * into m from public.men_profiles where user_id = uid;\n  select code, min_value into nxt from public.rank_rules where audience = 'man_spend' and min_value > m.spend_total order by min_value limit 1;\n  return jsonb_build_object(\n    'payment_mode', public.setting('payment_mode'),\n    'plans', (public.get_public_settings()) -> 'plans',\n    'rank_rules', (select jsonb_agg(jsonb_build_object('code', code, 'label', label, 'min_value', min_value, 'sort', sort) order by sort)\n                   from public.rank_rules where audience = 'man_spend'),\n    'access', public.man_access(uid),\n    'entitlement', (select jsonb_build_object('plan_code', plan_code, 'status', status, 'current_period_end', current_period_end,\n                    'cancel_at_period_end', cancel_at_period_end, 'source', source)\n                    from public.membership_entitlements where user_id = uid and status = 'active' limit 1),\n    'spend_total', m.spend_total, 'spend_rank', m.spend_rank_code,\n    'next_spend_rank', case when nxt.code is not null then jsonb_build_object('code', nxt.code, 'min_value', nxt.min_value) end,\n    'level', m.level, 'xp', m.xp, 'level_floor_xp', public.xp_for_level(m.level), 'next_level_xp', public.xp_for_level(m.level + 1),\n    'badges', public.badges(uid),\n    'payments', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'kind', kind, 'amount', amount, 'status', status,\n                 'is_sandbox', is_sandbox, 'plan_code', plan_code, 'booking_id', booking_id, 'created_at', created_at) order by created_at desc), '[]')\n                 from (select * from public.payments where user_id = uid order by created_at desc limit 30) p));\nend $$;\n\ncreate or replace function public.assert_sandbox() returns void\nlanguage plpgsql stable security definer set search_path = public as $$\nbegin\n  if public.setting('payment_mode') #>> '{}' <> 'sandbox' then\n    perform public.raise_app('LIVE_PAYMENTS_NOT_CONFIGURED',\n      '本番決済は未設定です。決済事業者の審査・契約完了後に有効化されます');\n  end if;\nend $$;\n\ncreate or replace function public.sandbox_subscribe(p_plan text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('man'); pl public.membership_plans; pay uuid;\nbegin\n  perform public.assert_sandbox();\n  select * into pl from public.membership_plans where code = p_plan and is_active;\n  if not found then perform public.raise_app('NOT_FOUND', 'プランが見つかりません'); end if;\n  update public.membership_entitlements set status = 'canceled', updated_at = now() where user_id = uid and status = 'active';\n  if pl.monthly_price > 0 then\n    insert into public.payments (user_id, kind, plan_code, amount, status, provider, is_sandbox, captured_at, note)\n      values (uid, 'subscription', pl.code, pl.monthly_price, 'captured', 'sandbox', true, now(), 'サンドボックス疑似決済')\n      returning id into pay;\n    insert into public.membership_entitlements (user_id, plan_code, current_period_end, source, external_ref)\n      values (uid, pl.code, now() + interval '30 days', 'sandbox', pay::text);\n  end if;\n  perform public.audit('membership.subscribe', 'user', uid::text, jsonb_build_object('plan', pl.code, 'sandbox', true));\n  perform public.notify(uid, 'membership', format('%s プランに変更しました（デモ）', pl.name),\n    'サンドボックスの疑似決済です。実際の請求は発生していません。', '/membership');\n  perform public.recompute_man(uid, 'membership_changed');\n  return public.membership_overview();\nend $$;\n\ncreate or replace function public.cancel_subscription() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('man');\nbegin\n  update public.membership_entitlements set cancel_at_period_end = true, updated_at = now() where user_id = uid and status = 'active';\n  if not found then perform public.raise_app('NOT_FOUND', '有効なプランがありません'); end if;\n  perform public.audit('membership.cancel', 'user', uid::text, '{}');\n  return public.membership_overview();\nend $$;\n\ncreate or replace function public.resume_subscription() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('man');\nbegin\n  update public.membership_entitlements set cancel_at_period_end = false, updated_at = now() where user_id = uid and status = 'active';\n  return public.membership_overview();\nend $$;\n\n-- ---------------------------------------------------------------- men: apply / request\ncreate or replace function public.submit_application(p_woman uuid, p_message text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('man'); e jsonb; v uuid;\nbegin\n  e := public.eligibility(uid, p_woman);\n  if not (e ->> 'can_apply')::boolean then\n    perform public.raise_app('NOT_ELIGIBLE', coalesce(e -> 'reasons' -> 0 ->> 'message', '現在申請できません'));\n  end if;\n  perform public.assert_clean_text(p_message);\n  insert into public.applications (man_id, woman_id, message) values (uid, p_woman, left(coalesce(p_message, ''), 500)) returning id into v;\n  perform public.notify(p_woman, 'application', '新しいプロフィール申請があります',\n    (select display_name from public.profiles where id = uid) || ' さんから申請が届きました', '/w/requests');\n  return jsonb_build_object('id', v, 'status', 'pending');\nend $$;\n\ncreate or replace function public.request_booking(p_slot uuid, p_message text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('man'); s public.availability_slots; e jsonb; v uuid;\nbegin\n  select * into s from public.availability_slots where id = p_slot for update;\n  if not found or s.status <> 'open' then perform public.raise_app('SLOT_UNAVAILABLE', 'この枠は現在受付していません'); end if;\n  if s.start_at <= now() then perform public.raise_app('SLOT_UNAVAILABLE', '開始時刻を過ぎた枠には申し込めません'); end if;\n  e := public.eligibility(uid, s.woman_id);\n  if not (e ->> 'can_request')::boolean then\n    perform public.raise_app(coalesce(e -> 'reasons' -> 0 ->> 'code', 'NOT_ELIGIBLE'),\n      coalesce(e -> 'reasons' -> 0 ->> 'message', '現在申し込みできません'));\n  end if;\n  perform public.assert_clean_text(p_message);\n  if exists (select 1 from public.bookings where slot_id = p_slot and man_id = uid and status in ('requested', 'accepted')) then\n    perform public.raise_app('DUPLICATE', 'この枠には申し込み済みです');\n  end if;\n  if exists (select 1 from public.bookings where man_id = uid and status = 'accepted'\n             and tstzrange(start_at, end_at) && tstzrange(s.start_at, s.end_at)) then\n    perform public.raise_app('BOOKING_CONFLICT', '同じ時間帯に確定済みの予約があります');\n  end if;\n  -- 価格・日時はサーバー側の枠情報から確定（クライアント値は使わない）\n  insert into public.bookings (man_id, woman_id, slot_id, start_at, end_at, area, plan_type, price, man_message)\n    values (uid, s.woman_id, s.id, s.start_at, s.end_at, s.area, s.plan_type, s.price, left(coalesce(p_message, ''), 500))\n    returning id into v;\n  insert into public.booking_events (booking_id, from_status, to_status, actor_id) values (v, null, 'requested', uid);\n  perform public.notify(s.woman_id, 'booking', '新しい予約申請があります',\n    (select display_name from public.profiles where id = uid) || ' さんから ' ||\n    to_char(s.start_at at time zone 'Asia/Tokyo', 'MM/DD HH24:MI') || ' の申請が届きました', '/booking/' || v);\n  return jsonb_build_object('id', v, 'status', 'requested');\nend $$;\n\ncreate or replace function public.redeem_share_link(p_code text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('man'); l public.share_links;\nbegin\n  select * into l from public.share_links where code = p_code and is_active;\n  if not found then perform public.raise_app('NOT_FOUND', 'この招待リンクは無効です'); end if;\n  if public.is_blocked_pair(uid, l.woman_id) then perform public.raise_app('NOT_FOUND', 'この招待リンクは無効です'); end if;\n  insert into public.applications (man_id, woman_id, status, source, decided_at)\n    values (uid, l.woman_id, 'approved', 'invite', now())\n    on conflict (man_id, woman_id) do update set status = 'approved', source = 'invite', decided_at = now();\n  perform public.ensure_conversation(uid, l.woman_id);\n  update public.share_links set uses = uses + 1 where id = l.id;\n  perform public.notify(l.woman_id, 'invite', '招待リンクからの登録がありました',\n    (select display_name from public.profiles where id = uid) || ' さんがあなたのプロフィールに参加しました', '/w/requests');\n  return jsonb_build_object('woman_id', l.woman_id);\nend $$;\n\ncreate or replace function public.get_share_link_preview(p_code text) returns jsonb\nlanguage sql stable security definer set search_path = public as $$\n  select jsonb_build_object('woman_id', l.woman_id, 'display_name', p.display_name, 'headline', w.headline)\n  from public.share_links l join public.profiles p on p.id = l.woman_id join public.women_profiles w on w.user_id = l.woman_id\n  where l.code = p_code and l.is_active and p.status = 'active'\n$$;\n\n-- ---------------------------------------------------------------- women: profile & settings\ncreate or replace function public.update_woman_profile(p_display_name text, p_area text, p_headline text, p_bio text,\n  p_areas text[], p_plan_types text[], p_is_published boolean) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman');\nbegin\n  if char_length(trim(coalesce(p_display_name, ''))) = 0 then perform public.raise_app('INVALID', '表示名を入力してください'); end if;\n  perform public.assert_clean_text(concat_ws(' ', p_display_name, p_headline, p_bio, array_to_string(p_areas, ' '), array_to_string(p_plan_types, ' ')));\n  if p_is_published and (select status from public.verification_states where user_id = uid) <> 'approved' then\n    perform public.raise_app('VERIFY_REQUIRED', 'プロフィールの公開には本人確認の完了が必要です');\n  end if;\n  if p_is_published and not exists (select 1 from public.profile_photos where user_id = uid and status = 'approved') then\n    perform public.raise_app('PHOTO_REQUIRED', 'プロフィールの公開には写真が1枚以上必要です');\n  end if;\n  update public.profiles set display_name = left(trim(p_display_name), 30), area = left(coalesce(p_area, ''), 30), updated_at = now() where id = uid;\n  update public.women_profiles set headline = left(coalesce(p_headline, ''), 60), bio = left(coalesce(p_bio, ''), 1000),\n    areas = coalesce(p_areas[1:5], '{}'), plan_types = coalesce(p_plan_types[1:6], '{}'), is_published = coalesce(p_is_published, false),\n    updated_at = now() where user_id = uid;\n  perform public.recompute_woman(uid, 'profile_updated');\n  return public.get_me();\nend $$;\n\ncreate or replace function public.set_accept_settings(p_accept_mode public.accept_mode, p_accept_requests boolean,\n  p_min_man_level int, p_ng_note text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman');\nbegin\n  update public.women_profiles set accept_mode = p_accept_mode, accept_requests = coalesce(p_accept_requests, true),\n    min_man_level = greatest(1, least(coalesce(p_min_man_level, 1), 50)), ng_note = left(coalesce(p_ng_note, ''), 500), updated_at = now()\n    where user_id = uid;\n  perform public.audit('woman.accept_settings', 'user', uid::text, jsonb_build_object('mode', p_accept_mode, 'accept', p_accept_requests));\n  return public.get_me();\nend $$;\n\ncreate or replace function public.upsert_venue(p_name text, p_area text, p_is_public boolean) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman');\nbegin\n  if char_length(trim(coalesce(p_name, ''))) = 0 then perform public.raise_app('INVALID', '店舗名を入力してください'); end if;\n  perform public.assert_clean_text(p_name);\n  insert into public.venue_references (woman_id, venue_name, area, is_public)\n    values (uid, left(trim(p_name), 60), left(coalesce(p_area, ''), 30), coalesce(p_is_public, false))\n    on conflict (woman_id) do update set\n      verify_status = case when public.venue_references.venue_name = excluded.venue_name then public.venue_references.verify_status else 'pending' end,\n      venue_name = excluded.venue_name, area = excluded.area, is_public = excluded.is_public;\n  perform public.recompute_woman(uid, 'venue_updated');\n  return public.get_me();\nend $$;\n\ncreate or replace function public.delete_venue() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman');\nbegin\n  delete from public.venue_references where woman_id = uid;\n  perform public.recompute_woman(uid, 'venue_deleted');\n  return public.get_me();\nend $$;\n\ncreate or replace function public.add_photo(p_path text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); n int; mx int;\nbegin\n  if p_path is null or split_part(p_path, '/', 1) <> uid::text or p_path like '%..%' then\n    perform public.raise_app('INVALID', '画像のパスが不正です');\n  end if;\n  mx := case when public.my_role() = 'woman' then 6 else 1 end;\n  select count(*) into n from public.profile_photos where user_id = uid;\n  if n >= mx then perform public.raise_app('LIMIT', format('写真は最大%s枚までです', mx)); end if;\n  insert into public.profile_photos (user_id, storage_path, sort_order, status)\n    values (uid, p_path, n, case when public.setting_bool('photo_auto_approve') then 'approved' else 'pending' end);\n  perform public.recompute_user(uid, 'photo_added');\n  return public.get_me();\nend $$;\n\ncreate or replace function public.delete_photo(p_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user();\nbegin\n  delete from public.profile_photos where id = p_id and user_id = uid;\n  if public.my_role() = 'woman' and not exists (select 1 from public.profile_photos where user_id = uid and status = 'approved') then\n    update public.women_profiles set is_published = false where user_id = uid;\n  end if;\n  perform public.recompute_user(uid, 'photo_deleted');\n  return public.get_me();\nend $$;\n\ncreate or replace function public.make_photo_primary(p_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user();\nbegin\n  update public.profile_photos set sort_order = case when id = p_id then -1 else sort_order end where user_id = uid;\n  with o as (select id, row_number() over (order by sort_order, created_at) - 1 as rn from public.profile_photos where user_id = uid)\n  update public.profile_photos p set sort_order = o.rn from o where p.id = o.id;\n  return public.get_me();\nend $$;\n\ncreate or replace function public.create_slot(p_start timestamptz, p_end timestamptz, p_area text, p_plan_type text,\n  p_price int, p_note text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman'); v uuid;\nbegin\n  if p_start <= now() then perform public.raise_app('INVALID', '開始日時は現在より後にしてください'); end if;\n  if p_end <= p_start or p_end - p_start > interval '8 hours' then\n    perform public.raise_app('INVALID', '終了時刻は開始より後、8時間以内にしてください');\n  end if;\n  if p_price is null or p_price < 0 or p_price > 1000000 then perform public.raise_app('INVALID', '希望料金が不正です'); end if;\n  perform public.assert_clean_text(concat_ws(' ', p_area, p_plan_type, p_note));\n  if exists (select 1 from public.availability_slots where woman_id = uid and status in ('open', 'booked')\n             and tstzrange(start_at, end_at) && tstzrange(p_start, p_end)) then\n    perform public.raise_app('SLOT_OVERLAP', '既存の枠と時間が重なっています');\n  end if;\n  insert into public.availability_slots (woman_id, start_at, end_at, area, plan_type, price, note)\n    values (uid, p_start, p_end, left(coalesce(p_area, ''), 30), left(coalesce(p_plan_type, '食事'), 20), p_price, left(coalesce(p_note, ''), 300))\n    returning id into v;\n  return jsonb_build_object('id', v);\nend $$;\n\ncreate or replace function public.list_my_slots() returns jsonb\nlanguage sql security definer set search_path = public as $$\n  select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'start_at', s.start_at, 'end_at', s.end_at, 'area', s.area,\n    'plan_type', s.plan_type, 'price', s.price, 'note', s.note, 'status', s.status,\n    'pending_requests', (select count(*) from public.bookings b where b.slot_id = s.id and b.status = 'requested')) order by s.start_at), '[]')\n  from public.availability_slots s where s.woman_id = auth.uid() and s.end_at > now() - interval '1 day' and s.status <> 'closed'\n$$;\n\ncreate or replace function public.close_slot(p_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman'); b record;\nbegin\n  if exists (select 1 from public.bookings where slot_id = p_id and status = 'accepted') then\n    perform public.raise_app('INVALID', '確定済みの予約がある枠は削除できません。予約をキャンセルしてください');\n  end if;\n  update public.availability_slots set status = 'closed' where id = p_id and woman_id = uid;\n  if not found then perform public.raise_app('NOT_FOUND', '枠が見つかりません'); end if;\n  for b in select id, man_id from public.bookings where slot_id = p_id and status = 'requested' loop\n    update public.bookings set status = 'declined', decline_reason = '枠の受付が終了しました', updated_at = now() where id = b.id;\n    insert into public.booking_events (booking_id, from_status, to_status, actor_id, note) values (b.id, 'requested', 'declined', uid, 'slot_closed');\n    perform public.notify(b.man_id, 'booking', '予約申請が成立しませんでした', '枠の受付が終了しました', '/booking/' || b.id);\n  end loop;\n  return public.list_my_slots();\nend $$;\n\n-- ---------------------------------------------------------------- women: incoming & decisions\ncreate or replace function public.list_incoming() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman');\nbegin\n  return jsonb_build_object(\n    'applications', (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'message', a.message, 'status', a.status, 'source', a.source,\n                     'created_at', a.created_at, 'man', public.man_summary(a.man_id)) order by a.created_at desc), '[]')\n                     from public.applications a where a.woman_id = uid and a.status = 'pending' and not public.is_blocked_pair(uid, a.man_id)),\n    'bookings', (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'start_at', b.start_at, 'end_at', b.end_at, 'area', b.area,\n                 'plan_type', b.plan_type, 'price', b.price, 'message', b.man_message, 'status', b.status, 'created_at', b.created_at,\n                 'man', public.man_summary(b.man_id)) order by b.start_at), '[]')\n                 from public.bookings b where b.woman_id = uid and b.status = 'requested' and not public.is_blocked_pair(uid, b.man_id)),\n    'customers', (select coalesce(jsonb_agg(jsonb_build_object('man', public.man_summary(a.man_id), 'source', a.source,\n                  'conversation_id', (select c.id from public.conversations c where c.man_id = a.man_id and c.woman_id = uid))\n                  order by a.decided_at desc), '[]')\n                  from public.applications a where a.woman_id = uid and a.status = 'approved' and not public.is_blocked_pair(uid, a.man_id)));\nend $$;\n\ncreate or replace function public.decide_application(p_id uuid, p_approve boolean) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman'); a public.applications;\nbegin\n  select * into a from public.applications where id = p_id and woman_id = uid for update;\n  if not found or a.status <> 'pending' then perform public.raise_app('NOT_FOUND', '申請が見つかりません'); end if;\n  update public.applications set status = case when p_approve then 'approved'::public.application_status else 'rejected' end,\n    decided_at = now() where id = p_id;\n  if p_approve then\n    perform public.ensure_conversation(a.man_id, uid);\n    perform public.notify(a.man_id, 'application', '申請が承認されました',\n      (select display_name from public.profiles where id = uid) || ' さんへ予約申請・メッセージができるようになりました', '/woman/' || uid);\n  else\n    perform public.notify(a.man_id, 'application', '申請の結果のお知らせ', '今回はご希望に添えませんでした', null);\n  end if;\n  return public.list_incoming();\nend $$;\n\ncreate or replace function public.transition_booking(p_id uuid, p_to public.booking_status, p_note text default '') returns public.bookings\nlanguage plpgsql security definer set search_path = public as $$\ndeclare b public.bookings; uid uuid := auth.uid(); ok boolean := false; adm boolean := public.is_admin(); prev public.booking_status;\nbegin\n  select * into b from public.bookings where id = p_id for update;\n  prev := b.status;\n  if not found or not (uid in (b.man_id, b.woman_id) or adm) then perform public.raise_app('NOT_FOUND', '予約が見つかりません'); end if;\n  ok := case\n    when b.status = 'requested' and p_to in ('accepted', 'declined') then uid = b.woman_id\n    when b.status = 'requested' and p_to = 'canceled' then uid in (b.man_id, b.woman_id) or adm\n    when b.status = 'accepted' and p_to = 'canceled' then uid in (b.man_id, b.woman_id) or adm\n    when b.status = 'accepted' and p_to = 'completed' then uid = b.woman_id or adm\n    when b.status in ('accepted', 'completed') and p_to = 'disputed' then uid in (b.man_id, b.woman_id)\n    when b.status = 'disputed' and p_to in ('completed', 'canceled') then adm\n    else false end;\n  if not ok then\n    perform public.raise_app('INVALID_TRANSITION', format('この予約は「%s」から「%s」へ変更できません', b.status, p_to));\n  end if;\n  update public.bookings set status = p_to, updated_at = now(),\n    accepted_at = case when p_to = 'accepted' then now() else accepted_at end,\n    completed_at = case when p_to = 'completed' then now() else completed_at end\n    where id = p_id returning * into b;\n  insert into public.booking_events (booking_id, from_status, to_status, actor_id, note)\n    values (p_id, prev, p_to, uid, coalesce(p_note, ''));\n  return b;\nend $$;\n\ncreate or replace function public.accept_booking(p_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman'); b public.bookings; other record; pay_status public.payment_status;\nbegin\n  select * into b from public.bookings where id = p_id and woman_id = uid;\n  if not found then perform public.raise_app('NOT_FOUND', '予約が見つかりません'); end if;\n  if b.status <> 'requested' then perform public.raise_app('INVALID_TRANSITION', 'この申請はすでに処理されています'); end if;\n  if public.is_blocked_pair(b.man_id, uid) or (select status from public.profiles where id = b.man_id) <> 'active' then\n    perform public.raise_app('NOT_ELIGIBLE', 'このお相手の申請は承認できません');\n  end if;\n  if b.start_at <= now() then perform public.raise_app('INVALID', '開始時刻を過ぎた申請は承認できません'); end if;\n  -- 同時承認による競合を直列化（女性・男性の両方でロック、順序固定でデッドロック回避）\n  perform pg_advisory_xact_lock(hashtextextended(least(b.man_id::text, uid::text), 0));\n  perform pg_advisory_xact_lock(hashtextextended(greatest(b.man_id::text, uid::text), 0));\n  if exists (select 1 from public.bookings x where x.id <> b.id and x.status = 'accepted'\n             and (x.woman_id = uid or x.man_id = b.man_id) and tstzrange(x.start_at, x.end_at) && tstzrange(b.start_at, b.end_at)) then\n    perform public.raise_app('BOOKING_CONFLICT', 'この時間帯は既に確定済みの予約と重なっているため承認できません');\n  end if;\n  if public.setting('payment_mode') #>> '{}' <> 'sandbox' then\n    perform public.raise_app('LIVE_PAYMENTS_NOT_CONFIGURED', '本番決済が未設定のため予約を確定できません');\n  end if;\n  perform public.transition_booking(p_id, 'accepted', '');\n  -- サンドボックス: 与信のみ（完了時に売上確定）\n  insert into public.payments (user_id, kind, booking_id, amount, status, provider, is_sandbox, note)\n    values (b.man_id, 'booking', b.id, b.price, 'authorized', 'sandbox', true, 'サンドボックス与信（実請求なし）');\n  if b.slot_id is not null then\n    update public.availability_slots set status = 'booked' where id = b.slot_id;\n    for other in select id, man_id from public.bookings where slot_id = b.slot_id and status = 'requested' and id <> b.id loop\n      update public.bookings set status = 'declined', decline_reason = 'この枠は他の予約で埋まりました', updated_at = now() where id = other.id;\n      insert into public.booking_events (booking_id, from_status, to_status, actor_id, note) values (other.id, 'requested', 'declined', uid, 'slot_filled');\n      perform public.notify(other.man_id, 'booking', '予約申請が成立しませんでした', 'この枠は他の予約で埋まりました', '/booking/' || other.id);\n    end loop;\n  end if;\n  perform public.ensure_conversation(b.man_id, uid);\n  perform public.notify(b.man_id, 'booking', '予約が確定しました',\n    (select display_name from public.profiles where id = uid) || ' さんが ' ||\n    to_char(b.start_at at time zone 'Asia/Tokyo', 'MM/DD HH24:MI') || ' の予約を承認しました', '/booking/' || b.id);\n  return public.get_booking(p_id);\nexception when exclusion_violation then\n  perform public.raise_app('BOOKING_CONFLICT', 'この時間帯は既に確定済みの予約と重なっているため承認できません');\nend $$;\n\ncreate or replace function public.decline_booking(p_id uuid, p_reason text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman'); b public.bookings;\nbegin\n  b := public.transition_booking(p_id, 'declined', coalesce(p_reason, ''));\n  update public.bookings set decline_reason = left(coalesce(nullif(p_reason, ''), '今回はご希望に添えませんでした'), 200) where id = p_id;\n  perform public.notify(b.man_id, 'booking', '予約申請の結果のお知らせ', '今回はご希望に添えませんでした', '/booking/' || b.id);\n  return public.get_booking(p_id);\nend $$;\n\ncreate or replace function public.settle_booking_payment(p_booking uuid, p_capture_amount int) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare pay public.payments; b public.bookings; fee int;\nbegin\n  select * into b from public.bookings where id = p_booking;\n  select * into pay from public.payments where booking_id = p_booking and kind = 'booking' for update;\n  if not found or pay.status <> 'authorized' then return; end if;\n  if p_capture_amount <= 0 then\n    update public.payments set status = 'voided', updated_at = now() where id = pay.id;\n    return;\n  end if;\n  update public.payments set status = 'captured', amount = p_capture_amount, captured_at = now(), updated_at = now() where id = pay.id;\n  fee := round(p_capture_amount * public.setting_num('platform_fee_rate', 0.2))::int;\n  insert into public.earnings_ledger (woman_id, booking_id, payment_id, entry_type, gross, fee, net, is_sandbox)\n    values (b.woman_id, b.id, pay.id, 'earning', p_capture_amount, fee, p_capture_amount - fee, pay.is_sandbox);\nend $$;\n\ncreate or replace function public.complete_booking(p_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); b public.bookings;\nbegin\n  select * into b from public.bookings where id = p_id;\n  if found and b.start_at > now() and not public.setting_bool('demo_mode') then\n    perform public.raise_app('TOO_EARLY', '開始時刻前は完了にできません');\n  end if;\n  b := public.transition_booking(p_id, 'completed', '');\n  perform public.settle_booking_payment(p_id, b.price);\n  perform public.recompute_woman(b.woman_id, 'booking_completed');\n  perform public.recompute_man(b.man_id, 'booking_completed');\n  perform public.notify(b.man_id, 'booking', 'ご利用ありがとうございました', '予約が完了しました。実績に反映されています。', '/booking/' || b.id);\n  perform public.notify(b.woman_id, 'earning', '報酬が確定しました（デモ）', '予約完了により報酬が台帳に記録されました。', '/earnings');\n  return public.get_booking(p_id);\nend $$;\n\ncreate or replace function public.cancel_booking(p_id uuid, p_reason text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); b public.bookings; prev public.booking_status; pol jsonb := public.setting('cancellation_policy');\n  late_fee int := 0; other uuid;\nbegin\n  select status into prev from public.bookings where id = p_id;\n  b := public.transition_booking(p_id, 'canceled', coalesce(p_reason, ''));\n  update public.bookings set cancel_reason = left(coalesce(p_reason, ''), 200), canceled_by = uid where id = p_id;\n  if prev = 'accepted' then\n    if uid = b.man_id and b.start_at - now() < make_interval(hours => coalesce((pol ->> 'free_until_hours')::int, 24)) then\n      late_fee := round(b.price * coalesce((pol ->> 'late_fee_rate')::numeric, 0))::int;\n    end if;\n    perform public.settle_booking_payment(p_id, late_fee);\n    if b.slot_id is not null then update public.availability_slots set status = 'open' where id = b.slot_id and start_at > now(); end if;\n    if late_fee > 0 then\n      perform public.recompute_woman(b.woman_id, 'late_cancel_fee');\n      perform public.recompute_man(b.man_id, 'late_cancel_fee');\n    end if;\n  end if;\n  other := case when uid = b.man_id then b.woman_id else b.man_id end;\n  perform public.notify(other, 'booking', '予約がキャンセルされました',\n    to_char(b.start_at at time zone 'Asia/Tokyo', 'MM/DD HH24:MI') || ' の予約がキャンセルされました', '/booking/' || b.id);\n  return public.get_booking(p_id);\nend $$;\n\ncreate or replace function public.open_dispute(p_id uuid, p_reason text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); b public.bookings;\nbegin\n  select * into b from public.bookings where id = p_id;\n  if found and b.status = 'completed' and b.completed_at < now() - make_interval(days => public.setting_num('dispute_window_days', 7)::int) then\n    perform public.raise_app('TOO_LATE', '申立て期間を過ぎています。お問い合わせからご連絡ください');\n  end if;\n  b := public.transition_booking(p_id, 'disputed', coalesce(p_reason, ''));\n  insert into public.reports (reporter_id, target_user_id, booking_id, category, detail)\n    values (uid, case when uid = b.man_id then b.woman_id else b.man_id end, p_id, 'booking_dispute', left(coalesce(p_reason, ''), 1000));\n  perform public.notify(case when uid = b.man_id then b.woman_id else b.man_id end, 'booking', '予約について申立てがありました',\n    '運営が内容を確認します', '/booking/' || b.id);\n  return public.get_booking(p_id);\nend $$;\n\ncreate or replace function public.request_refund(p_booking uuid, p_reason text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('man'); pay public.payments;\nbegin\n  select p.* into pay from public.payments p join public.bookings b on b.id = p.booking_id\n    where p.booking_id = p_booking and b.man_id = uid and p.status = 'captured';\n  if not found then perform public.raise_app('NOT_FOUND', '返金対象の決済がありません'); end if;\n  if exists (select 1 from public.refunds where payment_id = pay.id and status in ('requested', 'approved', 'processed')) then\n    perform public.raise_app('DUPLICATE', '返金申請は受付済みです');\n  end if;\n  insert into public.refunds (payment_id, booking_id, amount, reason, requested_by) values (pay.id, p_booking, pay.amount, left(coalesce(p_reason, ''), 500), uid);\n  return public.get_booking(p_booking);\nend $$;\n\n-- ---------------------------------------------------------------- bookings (both)\ncreate or replace function public.get_booking(p_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := auth.uid(); b public.bookings; is_man boolean; adm boolean := public.is_admin();\nbegin\n  select * into b from public.bookings where id = p_id;\n  if not found or not (uid in (b.man_id, b.woman_id) or adm) then perform public.raise_app('NOT_FOUND', '予約が見つかりません'); end if;\n  is_man := uid = b.man_id;\n  return jsonb_build_object(\n    'id', b.id, 'status', b.status, 'start_at', b.start_at, 'end_at', b.end_at, 'area', b.area, 'plan_type', b.plan_type,\n    'price', b.price, 'message', b.man_message, 'decline_reason', b.decline_reason, 'cancel_reason', b.cancel_reason,\n    'created_at', b.created_at, 'accepted_at', b.accepted_at, 'completed_at', b.completed_at,\n    'my_side', case when is_man then 'man' when uid = b.woman_id then 'woman' else 'admin' end,\n    'woman', public.woman_card(b.woman_id, null) - 'locked' - 'next_slot',\n    'man', public.man_summary(b.man_id),\n    'conversation_id', (select c.id from public.conversations c where c.man_id = b.man_id and c.woman_id = b.woman_id),\n    'payment', (select jsonb_build_object('status', p.status, 'amount', case when is_man or adm then p.amount end, 'is_sandbox', p.is_sandbox)\n                from public.payments p where p.booking_id = b.id and p.kind = 'booking'),\n    'earning', case when not is_man then (select jsonb_build_object('gross', sum(gross), 'fee', sum(fee), 'net', sum(net))\n                from public.earnings_ledger where booking_id = b.id) end,\n    'refund', (select jsonb_build_object('status', r.status, 'amount', r.amount) from public.refunds r where r.booking_id = b.id\n               order by r.created_at desc limit 1),\n    'events', (select coalesce(jsonb_agg(jsonb_build_object('to', to_status, 'from', from_status, 'at', created_at,\n               'by', case when actor_id = b.man_id then 'man' when actor_id = b.woman_id then 'woman' else 'system' end) order by id), '[]')\n               from public.booking_events where booking_id = b.id),\n    'cancellation_policy', public.setting('cancellation_policy'));\nend $$;\n\ncreate or replace function public.list_my_bookings(p_scope text default 'all') returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); r public.user_role := public.my_role();\nbegin\n  return (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'status', b.status, 'start_at', b.start_at, 'end_at', b.end_at,\n    'area', b.area, 'plan_type', b.plan_type, 'price', b.price,\n    'counterpart', case when r = 'man' then jsonb_build_object('id', b.woman_id, 'display_name', pw.display_name, 'photos', public.photo_paths(b.woman_id),\n                    'rank_code', (select rank_code from public.women_profiles where user_id = b.woman_id))\n                   else jsonb_build_object('id', b.man_id, 'display_name', pm.display_name, 'photos', public.photo_paths(b.man_id)) end)\n    order by case when p_scope = 'past' then -extract(epoch from b.start_at) else extract(epoch from b.start_at) end), '[]')\n    from public.bookings b join public.profiles pw on pw.id = b.woman_id join public.profiles pm on pm.id = b.man_id\n    where (b.man_id = uid or b.woman_id = uid)\n      and case p_scope\n        when 'upcoming' then b.status = 'accepted'\n        when 'pending' then b.status = 'requested'\n        when 'past' then b.status in ('completed', 'declined', 'canceled', 'disputed')\n        else true end);\nend $$;\n\n-- ---------------------------------------------------------------- women: dashboard & earnings\ncreate or replace function public.woman_dashboard() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman'); w public.women_profiles; nxt record; month_start timestamptz;\nbegin\n  select * into w from public.women_profiles where user_id = uid;\n  month_start := date_trunc('month', now() at time zone 'Asia/Tokyo') at time zone 'Asia/Tokyo';\n  select code, min_value into nxt from public.rank_rules where audience = 'woman' and min_value > w.rank_score order by min_value limit 1;\n  return jsonb_build_object(\n    'pending_applications', (select count(*) from public.applications where woman_id = uid and status = 'pending'),\n    'pending_bookings', (select count(*) from public.bookings where woman_id = uid and status = 'requested'),\n    'month_net', (select coalesce(sum(net), 0) from public.earnings_ledger where woman_id = uid and created_at >= month_start\n                  and entry_type in ('earning', 'reversal')),\n    'total_net', public.woman_earnings_net(uid),\n    'is_sandbox', public.setting('payment_mode') #>> '{}' = 'sandbox',\n    'upcoming', (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'start_at', b.start_at, 'end_at', b.end_at, 'area', b.area,\n                 'plan_type', b.plan_type, 'man_name', p.display_name) order by b.start_at), '[]')\n                 from public.bookings b join public.profiles p on p.id = b.man_id\n                 where b.woman_id = uid and b.status = 'accepted'),\n    'rank_code', w.rank_code, 'rank_score', w.rank_score,\n    'next_rank', case when nxt.code is not null then jsonb_build_object('code', nxt.code, 'min_value', nxt.min_value) end,\n    'rank_breakdown', (select breakdown - 'weights' from public.rank_snapshots where user_id = uid and audience = 'woman' order by computed_at desc limit 1),\n    'level', w.level, 'xp', w.xp, 'level_floor_xp', public.xp_for_level(w.level), 'next_level_xp', public.xp_for_level(w.level + 1),\n    'completed', public.completed_count(uid),\n    'is_published', w.is_published, 'accept_mode', w.accept_mode, 'accept_requests', w.accept_requests,\n    'badges', public.badges(uid));\nend $$;\n\ncreate or replace function public.get_earnings() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman');\nbegin\n  return jsonb_build_object(\n    'total_net', public.woman_earnings_net(uid),\n    'total_gross', (select coalesce(sum(gross), 0) from public.earnings_ledger where woman_id = uid and entry_type in ('earning', 'reversal')),\n    'total_fee', (select coalesce(sum(fee), 0) from public.earnings_ledger where woman_id = uid and entry_type in ('earning', 'reversal')),\n    'fee_rate', public.setting('platform_fee_rate'),\n    'is_sandbox', public.setting('payment_mode') #>> '{}' = 'sandbox',\n    'entries', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'type', e.entry_type, 'gross', e.gross, 'fee', e.fee, 'net', e.net,\n                'is_sandbox', e.is_sandbox, 'created_at', e.created_at, 'booking_id', e.booking_id,\n                'start_at', b.start_at, 'man_name', p.display_name) order by e.id desc), '[]')\n                from public.earnings_ledger e left join public.bookings b on b.id = e.booking_id\n                left join public.profiles p on p.id = b.man_id where e.woman_id = uid));\nend $$;\n\ncreate or replace function public.get_share_link(p_regenerate boolean default false) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman'); l public.share_links;\nbegin\n  if p_regenerate then update public.share_links set is_active = false where woman_id = uid and is_active; end if;\n  select * into l from public.share_links where woman_id = uid and is_active;\n  if not found then\n    insert into public.share_links (woman_id, code) values (uid, encode(extensions.gen_random_bytes(9), 'hex')) returning * into l;\n  end if;\n  return jsonb_build_object('code', l.code, 'uses', l.uses, 'created_at', l.created_at);\nend $$;\n\n-- ---------------------------------------------------------------- chat\ncreate or replace function public.list_conversations() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user();\nbegin\n  return (select coalesce(jsonb_agg(x.j order by x.sort_at desc nulls last), '[]') from (\n    select coalesce(c.last_message_at, c.created_at) as sort_at, jsonb_build_object(\n      'id', c.id, 'can_chat', public.can_chat(c.id, uid),\n      'counterpart', jsonb_build_object('id', o.id, 'display_name', o.display_name, 'photos', public.photo_paths(o.id), 'role', o.role),\n      'last_message', (select jsonb_build_object('body', m.body, 'created_at', m.created_at, 'mine', m.sender_id = uid)\n                       from public.messages m where m.conversation_id = c.id order by m.id desc limit 1),\n      'unread', (select count(*) from public.messages m where m.conversation_id = c.id and m.sender_id <> uid\n                 and m.id > coalesce((select last_read_id from public.conversation_reads r where r.conversation_id = c.id and r.user_id = uid), 0))) as j\n    from public.conversations c join public.profiles o on o.id = case when c.man_id = uid then c.woman_id else c.man_id end\n    where uid in (c.man_id, c.woman_id) and not public.is_blocked_pair(c.man_id, c.woman_id)) x);\nend $$;\n\ncreate or replace function public.get_messages(p_conversation uuid, p_after bigint default 0) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); c public.conversations; last_id bigint;\nbegin\n  select * into c from public.conversations where id = p_conversation;\n  if not found or uid not in (c.man_id, c.woman_id) or public.is_blocked_pair(c.man_id, c.woman_id) then\n    perform public.raise_app('NOT_FOUND', 'メッセージが見つかりません');\n  end if;\n  select max(id) into last_id from public.messages where conversation_id = p_conversation;\n  if last_id is not null then\n    insert into public.conversation_reads (conversation_id, user_id, last_read_id) values (p_conversation, uid, last_id)\n      on conflict (conversation_id, user_id) do update set last_read_id = greatest(public.conversation_reads.last_read_id, excluded.last_read_id);\n  end if;\n  return jsonb_build_object(\n    'can_chat', public.can_chat(p_conversation, uid),\n    'counterpart', (select jsonb_build_object('id', o.id, 'display_name', o.display_name, 'role', o.role, 'photos', public.photo_paths(o.id))\n                    from public.profiles o where o.id = case when c.man_id = uid then c.woman_id else c.man_id end),\n    'messages', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'body', m.body, 'created_at', m.created_at, 'mine', m.sender_id = uid)\n                 order by m.id), '[]')\n                 from (select * from public.messages where conversation_id = p_conversation and id > coalesce(p_after, 0)\n                       order by id desc limit 200) m));\nend $$;\n\ncreate or replace function public.send_message(p_conversation uuid, p_body text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); c public.conversations; v bigint; other uuid;\nbegin\n  if not public.can_chat(p_conversation, uid) then\n    perform public.raise_app('CHAT_FORBIDDEN', 'このお相手とはメッセージできません');\n  end if;\n  if char_length(trim(coalesce(p_body, ''))) = 0 then perform public.raise_app('INVALID', 'メッセージを入力してください'); end if;\n  perform public.assert_clean_text(p_body);\n  select * into c from public.conversations where id = p_conversation;\n  insert into public.messages (conversation_id, sender_id, body) values (p_conversation, uid, left(trim(p_body), 2000)) returning id into v;\n  update public.conversations set last_message_at = now() where id = p_conversation;\n  other := case when c.man_id = uid then c.woman_id else c.man_id end;\n  if not exists (select 1 from public.notifications where user_id = other and kind = 'message' and read_at is null\n                 and link = '/chat/' || p_conversation) then\n    perform public.notify(other, 'message', '新しいメッセージ', (select display_name from public.profiles where id = uid) || ' さんからメッセージが届きました',\n      '/chat/' || p_conversation);\n  end if;\n  return jsonb_build_object('id', v);\nend $$;\n\n-- ---------------------------------------------------------------- safety\ncreate or replace function public.block_user(p_target uuid) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); b record;\nbegin\n  if p_target = uid then perform public.raise_app('INVALID', '自分自身はブロックできません'); end if;\n  insert into public.blocks (blocker_id, blocked_id) values (uid, p_target) on conflict do nothing;\n  -- 進行中の申請は無効化（確定済み予約はキャンセル扱い）\n  for b in select id, status, man_id, woman_id from public.bookings\n           where ((man_id = uid and woman_id = p_target) or (woman_id = uid and man_id = p_target)) and status in ('requested', 'accepted') loop\n    update public.bookings set status = 'canceled', cancel_reason = 'blocked', canceled_by = uid, updated_at = now() where id = b.id;\n    insert into public.booking_events (booking_id, from_status, to_status, actor_id, note) values (b.id, b.status, 'canceled', uid, 'blocked');\n    perform public.settle_booking_payment(b.id, 0);\n  end loop;\n  update public.applications set status = 'withdrawn' where ((man_id = uid and woman_id = p_target) or (woman_id = uid and man_id = p_target))\n    and status = 'pending';\n  perform public.audit('user.block', 'user', p_target::text, '{}');\n  return jsonb_build_object('blocked', true);\nend $$;\n\ncreate or replace function public.unblock_user(p_target uuid) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user();\nbegin\n  delete from public.blocks where blocker_id = uid and blocked_id = p_target;\n  return jsonb_build_object('blocked', false);\nend $$;\n\ncreate or replace function public.list_blocks() returns jsonb\nlanguage sql security definer set search_path = public as $$\n  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'display_name', p.display_name, 'created_at', b.created_at) order by b.created_at desc), '[]')\n  from public.blocks b join public.profiles p on p.id = b.blocked_id where b.blocker_id = auth.uid()\n$$;\n\ncreate or replace function public.report_user(p_target uuid, p_category text, p_detail text, p_booking uuid default null,\n  p_message bigint default null) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); v uuid;\nbegin\n  if p_target = uid then perform public.raise_app('INVALID', '自分自身は通報できません'); end if;\n  if p_category not in ('prohibited_service', 'harassment', 'solicitation', 'fake_profile', 'underage', 'safety', 'no_show', 'other') then\n    perform public.raise_app('INVALID', '通報カテゴリが不正です');\n  end if;\n  if p_message is not null and not exists (select 1 from public.messages m join public.conversations c on c.id = m.conversation_id\n      where m.id = p_message and uid in (c.man_id, c.woman_id)) then\n    perform public.raise_app('INVALID', '対象メッセージが見つかりません');\n  end if;\n  insert into public.reports (reporter_id, target_user_id, booking_id, message_id, category, detail)\n    values (uid, p_target, p_booking, p_message, p_category, left(coalesce(p_detail, ''), 2000)) returning id into v;\n  perform public.audit('report.create', 'user', p_target::text, jsonb_build_object('report', v, 'category', p_category));\n  return jsonb_build_object('id', v);\nend $$;\n\ncreate or replace function public.submit_inquiry(p_category text, p_body text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := auth.uid(); v uuid;\nbegin\n  if uid is null then perform public.raise_app('AUTH_REQUIRED', 'ログインが必要です'); end if;\n  if char_length(trim(coalesce(p_body, ''))) < 5 then perform public.raise_app('INVALID', '内容を5文字以上で入力してください'); end if;\n  insert into public.inquiries (user_id, category, body) values (uid, p_category, left(p_body, 3000)) returning id into v;\n  return jsonb_build_object('id', v);\nend $$;\n\ncreate or replace function public.list_my_inquiries() returns jsonb\nlanguage sql security definer set search_path = public as $$\n  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'category', category, 'body', body, 'status', status,\n    'admin_reply', admin_reply, 'created_at', created_at) order by created_at desc), '[]')\n  from public.inquiries where user_id = auth.uid()\n$$;\n\n-- 退会申請: 即時に非公開化・進行中予約をキャンセルし、運営が匿名化処理を行う（会計記録は法定期間保持）\ncreate or replace function public.request_account_deletion(p_reason text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); b record;\nbegin\n  for b in select id, status from public.bookings where (man_id = uid or woman_id = uid) and status in ('requested', 'accepted') loop\n    update public.bookings set status = 'canceled', cancel_reason = 'account_deletion', canceled_by = uid, updated_at = now() where id = b.id;\n    insert into public.booking_events (booking_id, from_status, to_status, actor_id, note) values (b.id, b.status, 'canceled', uid, 'account_deletion');\n    perform public.settle_booking_payment(b.id, 0);\n  end loop;\n  update public.women_profiles set is_published = false where user_id = uid;\n  update public.membership_entitlements set cancel_at_period_end = true where user_id = uid and status = 'active';\n  update public.share_links set is_active = false where woman_id = uid;\n  insert into public.inquiries (user_id, category, body) values (uid, 'deletion', coalesce(nullif(trim(p_reason), ''), '（理由未記入）'));\n  update public.profiles set status = 'deletion_requested', status_reason = 'user_request', updated_at = now() where id = uid;\n  perform public.audit('user.deletion_requested', 'user', uid::text, '{}');\n  return jsonb_build_object('status', 'deletion_requested');\nend $$;\n"},{"name":"20261028000004_admin_rpc.sql","sql":"-- 運営者向け RPC。すべて require_admin() で検証し、変更系は audit_events に記録する。\n\ncreate or replace function public.admin_dashboard() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare decided int; ok int;\nbegin\n  perform public.require_admin();\n  select count(*) filter (where status in ('accepted', 'completed', 'declined', 'canceled', 'disputed')),\n         count(*) filter (where status in ('accepted', 'completed'))\n    into decided, ok from public.bookings;\n  return jsonb_build_object(\n    'users', (select jsonb_build_object(\n       'total', count(*) filter (where role <> 'admin'),\n       'women', count(*) filter (where role = 'woman'), 'men', count(*) filter (where role = 'man'),\n       'suspended', count(*) filter (where status = 'suspended'),\n       'deletion_requested', count(*) filter (where status = 'deletion_requested'),\n       'new_7d', count(*) filter (where role <> 'admin' and created_at > now() - interval '7 days')) from public.profiles),\n    'verification_pending', (select count(*) from public.verification_states where status = 'pending'),\n    'venue_pending', (select count(*) from public.venue_references where verify_status = 'pending'),\n    'photos_pending', (select count(*) from public.profile_photos where status = 'pending'),\n    'applications', (select count(*) from public.applications),\n    'bookings', (select coalesce(jsonb_object_agg(status, n), '{}') from (select status, count(*) n from public.bookings group by status) s),\n    'booking_total', (select count(*) from public.bookings),\n    'success_rate', case when decided > 0 then round(ok::numeric / decided * 100, 1) else null end,\n    'revenue', (select jsonb_build_object(\n       'subscription', coalesce(sum(amount) filter (where kind = 'subscription' and status = 'captured'), 0),\n       'booking_gross', coalesce(sum(amount) filter (where kind = 'booking' and status in ('captured', 'refunded')), 0))\n       from public.payments where is_sandbox = (public.setting('payment_mode') #>> '{}' = 'sandbox')),\n    'platform_fee', (select coalesce(sum(fee), 0) from public.earnings_ledger where is_sandbox = (public.setting('payment_mode') #>> '{}' = 'sandbox')),\n    'reports_open', (select count(*) from public.reports where status in ('open', 'reviewing')),\n    'disputes_open', (select count(*) from public.bookings where status = 'disputed'),\n    'refunds_open', (select count(*) from public.refunds where status = 'requested'),\n    'inquiries_open', (select count(*) from public.inquiries where status = 'open'),\n    'payment_mode', public.setting('payment_mode'));\nend $$;\n\ncreate or replace function public.admin_list_users(p_role text default null, p_status text default null,\n  p_verification text default null, p_query text default null) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  return (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'role', p.role, 'display_name', p.display_name, 'area', p.area,\n    'status', p.status, 'created_at', p.created_at, 'email', u.email, 'verification', v.status,\n    'rank', coalesce(w.rank_code, m.spend_rank_code), 'level', coalesce(w.level, m.level), 'is_published', w.is_published)\n    order by p.created_at desc), '[]')\n    from public.profiles p join auth.users u on u.id = p.id\n    left join public.verification_states v on v.user_id = p.id\n    left join public.women_profiles w on w.user_id = p.id left join public.men_profiles m on m.user_id = p.id\n    where (p_role is null or p_role = '' or p.role::text = p_role)\n      and (p_status is null or p_status = '' or p.status::text = p_status)\n      and (p_verification is null or p_verification = '' or v.status::text = p_verification)\n      and (p_query is null or p_query = '' or p.display_name ilike '%' || p_query || '%' or u.email ilike '%' || p_query || '%')\n    limit 300);\nend $$;\n\ncreate or replace function public.admin_get_user(p_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare p public.profiles;\nbegin\n  perform public.require_admin();\n  select * into p from public.profiles where id = p_id;\n  if not found then perform public.raise_app('NOT_FOUND', 'ユーザーが見つかりません'); end if;\n  return jsonb_build_object(\n    'profile', to_jsonb(p), 'email', (select email from auth.users where id = p_id),\n    'verification', (select to_jsonb(v) from public.verification_states v where v.user_id = p_id),\n    'woman', (select to_jsonb(w) from public.women_profiles w where w.user_id = p_id),\n    'man', (select to_jsonb(m) from public.men_profiles m where m.user_id = p_id),\n    'access', case when p.role = 'man' then public.man_access(p_id) end,\n    'venue', (select to_jsonb(x) from public.venue_references x where x.woman_id = p_id),\n    'photos', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'path', storage_path, 'status', status) order by sort_order), '[]')\n               from public.profile_photos where user_id = p_id),\n    'rank_snapshots', (select coalesce(jsonb_agg(to_jsonb(s) order by s.computed_at desc), '[]')\n                       from (select * from public.rank_snapshots where user_id = p_id order by computed_at desc limit 20) s),\n    'reports_against', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'category', category, 'status', status, 'created_at', created_at)), '[]')\n                        from public.reports where target_user_id = p_id),\n    'bookings', (select jsonb_object_agg(status, n) from (select status, count(*) n from public.bookings\n                 where man_id = p_id or woman_id = p_id group by status) s),\n    'earnings_net', case when p.role = 'woman' then public.woman_earnings_net(p_id) end,\n    'entitlement', (select to_jsonb(e) from public.membership_entitlements e where e.user_id = p_id and e.status = 'active'));\nend $$;\n\ncreate or replace function public.admin_set_verification(p_user uuid, p_status public.verification_status, p_reason text default null) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare adm uuid := public.require_admin();\nbegin\n  update public.verification_states set status = p_status, reviewed_at = now(), reviewed_by = adm,\n    rejection_reason = case when p_status = 'rejected' then coalesce(p_reason, '書類を確認できませんでした') end where user_id = p_user;\n  if not found then perform public.raise_app('NOT_FOUND', 'ユーザーが見つかりません'); end if;\n  if p_status <> 'approved' then update public.women_profiles set is_published = false where user_id = p_user; end if;\n  perform public.audit('admin.verification', 'user', p_user::text, jsonb_build_object('status', p_status, 'reason', p_reason));\n  perform public.notify(p_user, 'verification', case when p_status = 'approved' then '本人確認が完了しました' else '本人確認の結果のお知らせ' end,\n    case when p_status = 'approved' then '申し込み・予約機能をご利用いただけます' else coalesce(p_reason, '内容をご確認ください') end, '/verification');\n  perform public.recompute_user(p_user, 'verification_reviewed');\n  return public.admin_get_user(p_user);\nend $$;\n\ncreate or replace function public.admin_set_user_status(p_user uuid, p_status public.account_status, p_reason text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare adm uuid := public.require_admin();\nbegin\n  if p_user = adm then perform public.raise_app('INVALID', '自分自身の状態は変更できません'); end if;\n  if p_status = 'deleted' then perform public.raise_app('INVALID', '削除は退会処理から実行してください'); end if;\n  update public.profiles set status = p_status, status_reason = p_reason, updated_at = now() where id = p_user;\n  if p_status = 'suspended' then\n    update public.women_profiles set is_published = false where user_id = p_user;\n    perform public.notify(p_user, 'system', 'アカウントが一時停止されました', coalesce(p_reason, '') || '（異議申立ては問い合わせから可能です）', '/support');\n  end if;\n  perform public.audit('admin.user_status', 'user', p_user::text, jsonb_build_object('status', p_status, 'reason', p_reason));\n  return public.admin_get_user(p_user);\nend $$;\n\ncreate or replace function public.admin_set_review(p_woman uuid, p_score int, p_note text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  update public.women_profiles set review_score = greatest(0, least(p_score, 100)), review_note = coalesce(p_note, '') where user_id = p_woman;\n  if not found then perform public.raise_app('NOT_FOUND', '女性プロフィールが見つかりません'); end if;\n  perform public.audit('admin.review_score', 'user', p_woman::text, jsonb_build_object('score', p_score));\n  perform public.recompute_woman(p_woman, 'admin_review');\n  return public.admin_get_user(p_woman);\nend $$;\n\ncreate or replace function public.admin_set_venue_status(p_venue uuid, p_status public.verification_status) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare adm uuid := public.require_admin(); w uuid;\nbegin\n  update public.venue_references set verify_status = p_status, verified_by = adm, verified_at = now() where id = p_venue returning woman_id into w;\n  if w is null then perform public.raise_app('NOT_FOUND', '店舗情報が見つかりません'); end if;\n  perform public.audit('admin.venue', 'venue', p_venue::text, jsonb_build_object('status', p_status));\n  perform public.recompute_woman(w, 'venue_reviewed');\n  return public.admin_get_user(w);\nend $$;\n\ncreate or replace function public.admin_review_queue() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  return jsonb_build_object(\n    'verifications', (select coalesce(jsonb_agg(jsonb_build_object('user_id', v.user_id, 'display_name', p.display_name, 'role', p.role,\n                      'birth_year', v.birth_year, 'method', v.method, 'submitted_at', v.submitted_at) order by v.submitted_at), '[]')\n                      from public.verification_states v join public.profiles p on p.id = v.user_id where v.status = 'pending'),\n    'venues', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'woman_id', x.woman_id, 'display_name', p.display_name,\n               'venue_name', x.venue_name, 'area', x.area, 'is_public', x.is_public, 'created_at', x.created_at)), '[]')\n               from public.venue_references x join public.profiles p on p.id = x.woman_id where x.verify_status = 'pending'),\n    'photos', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'user_id', f.user_id, 'display_name', p.display_name,\n               'path', f.storage_path, 'created_at', f.created_at)), '[]')\n               from public.profile_photos f join public.profiles p on p.id = f.user_id where f.status = 'pending'),\n    'deletions', (select coalesce(jsonb_agg(jsonb_build_object('user_id', p.id, 'display_name', p.display_name, 'role', p.role,\n                  'updated_at', p.updated_at)), '[]') from public.profiles p where p.status = 'deletion_requested'));\nend $$;\n\ncreate or replace function public.admin_moderate_photo(p_photo uuid, p_status text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare u uuid;\nbegin\n  perform public.require_admin();\n  if p_status not in ('approved', 'rejected') then perform public.raise_app('INVALID', '不正なステータスです'); end if;\n  update public.profile_photos set status = p_status where id = p_photo returning user_id into u;\n  if u is null then perform public.raise_app('NOT_FOUND', '写真が見つかりません'); end if;\n  perform public.audit('admin.photo', 'photo', p_photo::text, jsonb_build_object('status', p_status));\n  perform public.recompute_user(u, 'photo_reviewed');\n  return public.admin_review_queue();\nend $$;\n\n-- ---------------------------------------------------------------- settings, plans, ranks\ncreate or replace function public.admin_list_settings() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  return jsonb_build_object(\n    'settings', (select jsonb_agg(to_jsonb(s) order by key) from public.app_settings s),\n    'plans', (select jsonb_agg(to_jsonb(p) order by sort) from public.membership_plans p),\n    'rank_rules', (select jsonb_agg(to_jsonb(r) order by audience, sort) from public.rank_rules r));\nend $$;\n\ncreate or replace function public.admin_update_setting(p_key text, p_value jsonb) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare adm uuid := public.require_admin(); old jsonb;\nbegin\n  select value into old from public.app_settings where key = p_key;\n  if not found then perform public.raise_app('NOT_FOUND', '設定キーが見つかりません'); end if;\n  if p_key = 'payment_mode' and p_value #>> '{}' not in ('sandbox', 'live') then\n    perform public.raise_app('INVALID', 'payment_mode は sandbox / live のみ指定できます');\n  end if;\n  update public.app_settings set value = p_value, updated_at = now(), updated_by = adm where key = p_key;\n  perform public.audit('admin.setting', 'setting', p_key, jsonb_build_object('old', old, 'new', p_value));\n  return public.admin_list_settings();\nend $$;\n\ncreate or replace function public.admin_upsert_plan(p_code text, p_name text, p_price int, p_unlock_rank text, p_perks jsonb,\n  p_is_active boolean, p_sort int) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  if not exists (select 1 from public.rank_rules where audience = 'woman' and code = p_unlock_rank) then\n    perform public.raise_app('INVALID', '解放ランクが不正です');\n  end if;\n  insert into public.membership_plans (code, name, monthly_price, unlock_rank, perks, is_active, sort)\n    values (upper(p_code), p_name, p_price, p_unlock_rank, coalesce(p_perks, '[]'), coalesce(p_is_active, true), coalesce(p_sort, 0))\n    on conflict (code) do update set name = excluded.name, monthly_price = excluded.monthly_price, unlock_rank = excluded.unlock_rank,\n      perks = excluded.perks, is_active = excluded.is_active, sort = excluded.sort, updated_at = now();\n  perform public.audit('admin.plan', 'plan', upper(p_code), jsonb_build_object('price', p_price, 'unlock', p_unlock_rank, 'active', p_is_active));\n  return public.admin_list_settings();\nend $$;\n\ncreate or replace function public.admin_upsert_rank_rule(p_audience text, p_code text, p_label text, p_min numeric, p_sort int) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare u record;\nbegin\n  perform public.require_admin();\n  insert into public.rank_rules (audience, code, label, min_value, sort) values (p_audience, p_code, p_label, p_min, p_sort)\n    on conflict (audience, code) do update set label = excluded.label, min_value = excluded.min_value, sort = excluded.sort;\n  perform public.audit('admin.rank_rule', 'rank_rule', p_audience || ':' || p_code, jsonb_build_object('min', p_min, 'sort', p_sort));\n  for u in select id from public.profiles where role = case when p_audience = 'woman' then 'woman'::public.user_role else 'man' end loop\n    perform public.recompute_user(u.id, 'rank_rule_changed');\n  end loop;\n  return public.admin_list_settings();\nend $$;\n\n-- ---------------------------------------------------------------- bookings / disputes / refunds\ncreate or replace function public.admin_list_bookings(p_status text default null) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  return (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'status', b.status, 'start_at', b.start_at, 'end_at', b.end_at,\n    'price', b.price, 'area', b.area, 'man_name', pm.display_name, 'woman_name', pw.display_name, 'man_id', b.man_id, 'woman_id', b.woman_id,\n    'payment_status', (select status from public.payments where booking_id = b.id and kind = 'booking'),\n    'refund_status', (select status from public.refunds where booking_id = b.id order by created_at desc limit 1),\n    'created_at', b.created_at) order by b.created_at desc), '[]')\n    from (select * from public.bookings where p_status is null or p_status = '' or status::text = p_status order by created_at desc limit 300) b\n    join public.profiles pm on pm.id = b.man_id join public.profiles pw on pw.id = b.woman_id);\nend $$;\n\ncreate or replace function public.process_refund(p_refund uuid) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare r public.refunds; pay public.payments; earned record;\nbegin\n  select * into r from public.refunds where id = p_refund for update;\n  select * into pay from public.payments where id = r.payment_id for update;\n  update public.refunds set status = 'processed', decided_by = auth.uid(), decided_at = now() where id = r.id;\n  update public.payments set status = 'refunded', updated_at = now() where id = pay.id;\n  select sum(gross) g, sum(fee) f, sum(net) n into earned from public.earnings_ledger where payment_id = pay.id;\n  if pay.kind = 'booking' and coalesce(earned.g, 0) > 0 then\n    insert into public.earnings_ledger (woman_id, booking_id, payment_id, entry_type, gross, fee, net, is_sandbox)\n      select b.woman_id, b.id, pay.id, 'reversal', -earned.g, -earned.f, -earned.n, pay.is_sandbox from public.bookings b where b.id = pay.booking_id;\n    perform public.recompute_woman((select woman_id from public.bookings where id = pay.booking_id), 'refund');\n  end if;\n  perform public.recompute_man(pay.user_id, 'refund');\n  perform public.notify(pay.user_id, 'payment', '返金が処理されました（デモ）', format('%s円の返金を記録しました', r.amount), null);\nend $$;\n\ncreate or replace function public.admin_resolve_dispute(p_booking uuid, p_outcome text, p_note text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare b public.bookings; pay public.payments; rid uuid;\nbegin\n  perform public.require_admin();\n  select * into b from public.bookings where id = p_booking;\n  if not found or b.status <> 'disputed' then perform public.raise_app('INVALID', '申立て中の予約ではありません'); end if;\n  select * into pay from public.payments where booking_id = p_booking and kind = 'booking';\n  if p_outcome = 'complete' then\n    perform public.transition_booking(p_booking, 'completed', coalesce(p_note, ''));\n    perform public.settle_booking_payment(p_booking, b.price);\n  elsif p_outcome = 'cancel' then\n    perform public.transition_booking(p_booking, 'canceled', coalesce(p_note, ''));\n    perform public.settle_booking_payment(p_booking, 0);\n  elsif p_outcome = 'refund' then\n    perform public.transition_booking(p_booking, 'canceled', coalesce(p_note, ''));\n    if pay.status = 'captured' then\n      insert into public.refunds (payment_id, booking_id, amount, reason, status, requested_by)\n        values (pay.id, p_booking, pay.amount, coalesce(p_note, '申立てによる返金'), 'approved', auth.uid()) returning id into rid;\n      perform public.process_refund(rid);\n    else\n      perform public.settle_booking_payment(p_booking, 0);\n    end if;\n  else\n    perform public.raise_app('INVALID', '不正な処理区分です');\n  end if;\n  update public.reports set status = 'actioned', admin_note = coalesce(p_note, ''), resolved_by = auth.uid(), resolved_at = now()\n    where booking_id = p_booking and category = 'booking_dispute' and status in ('open', 'reviewing');\n  perform public.recompute_woman(b.woman_id, 'dispute_resolved');\n  perform public.recompute_man(b.man_id, 'dispute_resolved');\n  perform public.audit('admin.dispute', 'booking', p_booking::text, jsonb_build_object('outcome', p_outcome, 'note', p_note));\n  perform public.notify(b.man_id, 'booking', '申立ての結果', '運営が予約の申立てを処理しました', '/booking/' || b.id);\n  perform public.notify(b.woman_id, 'booking', '申立ての結果', '運営が予約の申立てを処理しました', '/booking/' || b.id);\n  return public.get_booking(p_booking);\nend $$;\n\ncreate or replace function public.admin_list_refunds(p_status text default null) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  return (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'amount', r.amount, 'reason', r.reason, 'status', r.status,\n    'booking_id', r.booking_id, 'requested_by', p.display_name, 'created_at', r.created_at) order by r.created_at desc), '[]')\n    from public.refunds r left join public.profiles p on p.id = r.requested_by\n    where p_status is null or p_status = '' or r.status = p_status);\nend $$;\n\ncreate or replace function public.admin_decide_refund(p_id uuid, p_approve boolean) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare r public.refunds;\nbegin\n  perform public.require_admin();\n  select * into r from public.refunds where id = p_id;\n  if not found or r.status <> 'requested' then perform public.raise_app('INVALID', '処理待ちの返金申請ではありません'); end if;\n  if p_approve then\n    update public.refunds set status = 'approved' where id = p_id;\n    perform public.process_refund(p_id);\n  else\n    update public.refunds set status = 'rejected', decided_by = auth.uid(), decided_at = now() where id = p_id;\n    perform public.notify(r.requested_by, 'payment', '返金申請の結果', '今回の返金申請は承認されませんでした。詳細は問い合わせへ', null);\n  end if;\n  perform public.audit('admin.refund', 'refund', p_id::text, jsonb_build_object('approve', p_approve));\n  return public.admin_list_refunds(null);\nend $$;\n\n-- ---------------------------------------------------------------- reports / audit / inquiries / deletion\ncreate or replace function public.admin_list_reports(p_status text default null) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  return (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'category', r.category, 'detail', r.detail, 'status', r.status,\n    'admin_note', r.admin_note, 'created_at', r.created_at, 'booking_id', r.booking_id,\n    'reporter', jsonb_build_object('id', a.id, 'display_name', a.display_name, 'role', a.role),\n    'target', jsonb_build_object('id', t.id, 'display_name', t.display_name, 'role', t.role, 'status', t.status),\n    'message', (select m.body from public.messages m where m.id = r.message_id)) order by r.created_at desc), '[]')\n    from public.reports r join public.profiles a on a.id = r.reporter_id join public.profiles t on t.id = r.target_user_id\n    where p_status is null or p_status = '' or r.status::text = p_status);\nend $$;\n\ncreate or replace function public.admin_update_report(p_id uuid, p_status public.report_status, p_note text, p_suspend boolean) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare r public.reports;\nbegin\n  perform public.require_admin();\n  update public.reports set status = p_status, admin_note = coalesce(p_note, ''),\n    resolved_by = case when p_status in ('actioned', 'dismissed') then auth.uid() end,\n    resolved_at = case when p_status in ('actioned', 'dismissed') then now() end where id = p_id returning * into r;\n  if r.id is null then perform public.raise_app('NOT_FOUND', '通報が見つかりません'); end if;\n  if coalesce(p_suspend, false) then\n    perform public.admin_set_user_status(r.target_user_id, 'suspended', coalesce(p_note, '利用規約違反の疑い'));\n  end if;\n  perform public.recompute_user(r.target_user_id, 'report_' || p_status);\n  perform public.audit('admin.report', 'report', p_id::text, jsonb_build_object('status', p_status, 'suspend', p_suspend));\n  return public.admin_list_reports(null);\nend $$;\n\ncreate or replace function public.admin_list_audit(p_limit int default 100) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  return (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'action', e.action, 'target_type', e.target_type, 'target_id', e.target_id,\n    'detail', e.detail, 'created_at', e.created_at, 'actor', p.display_name) order by e.id desc), '[]')\n    from (select * from public.audit_events order by id desc limit least(coalesce(p_limit, 100), 500)) e\n    left join public.profiles p on p.id = e.actor_id);\nend $$;\n\ncreate or replace function public.admin_list_inquiries(p_status text default null) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  return (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'category', i.category, 'body', i.body, 'status', i.status,\n    'admin_reply', i.admin_reply, 'created_at', i.created_at, 'user', jsonb_build_object('id', p.id, 'display_name', p.display_name,\n    'role', p.role, 'status', p.status)) order by i.created_at desc), '[]')\n    from public.inquiries i join public.profiles p on p.id = i.user_id\n    where p_status is null or p_status = '' or i.status = p_status);\nend $$;\n\ncreate or replace function public.admin_reply_inquiry(p_id uuid, p_reply text, p_status text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare u uuid;\nbegin\n  perform public.require_admin();\n  update public.inquiries set admin_reply = p_reply, status = p_status, updated_at = now() where id = p_id returning user_id into u;\n  if u is null then perform public.raise_app('NOT_FOUND', '問い合わせが見つかりません'); end if;\n  perform public.notify(u, 'support', '問い合わせへの回答があります', left(coalesce(p_reply, ''), 80), '/support');\n  perform public.audit('admin.inquiry', 'inquiry', p_id::text, jsonb_build_object('status', p_status));\n  return public.admin_list_inquiries(null);\nend $$;\n\n-- 退会処理: 個人を特定できる情報を消去・匿名化。予約・決済・台帳は会計・紛争対応のため匿名状態で保持。\ncreate or replace function public.admin_process_deletion(p_user uuid) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  if (select status from public.profiles where id = p_user) <> 'deletion_requested' then\n    perform public.raise_app('INVALID', '退会申請中のユーザーではありません');\n  end if;\n  delete from public.profile_photos where user_id = p_user;\n  delete from public.venue_references where woman_id = p_user;\n  delete from public.share_links where woman_id = p_user;\n  delete from public.notifications where user_id = p_user;\n  update public.messages set body = '（退会したユーザーのメッセージは削除されました）' where sender_id = p_user;\n  update public.women_profiles set headline = '', bio = '', ng_note = '', areas = '{}', is_published = false where user_id = p_user;\n  update public.men_profiles set bio = '' where user_id = p_user;\n  update public.verification_states set birth_year = null where user_id = p_user;\n  update public.profiles set display_name = '退会済みユーザー', area = '', status = 'deleted', updated_at = now() where id = p_user;\n  update auth.users set email = 'deleted+' || p_user::text || '@invalid.local', encrypted_password = '' where id = p_user;\n  perform public.audit('admin.deletion_processed', 'user', p_user::text, '{}');\n  return jsonb_build_object('status', 'deleted');\nend $$;\n\ncreate or replace function public.admin_payment_status() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  return jsonb_build_object(\n    'payment_mode', public.setting('payment_mode'),\n    'providers', jsonb_build_array(\n      jsonb_build_object('name', 'sandbox', 'status', 'active', 'note', '疑似決済。実請求・実送金は行われません'),\n      jsonb_build_object('name', 'app_store / google_play（RevenueCat 想定）', 'status', 'not_configured', 'note', 'デジタル会員機能（サブスク）用。ストア審査・契約後に設定'),\n      jsonb_build_object('name', '決済代行（Stripe 等）', 'status', 'not_configured', 'note', '対面の予約サービス用。事業者審査・法令確認後に設定')),\n    'counts', (select jsonb_object_agg(k, n) from (select kind::text || ':' || status::text k, count(*) n from public.payments group by 1) s),\n    'sandbox_payments', (select count(*) from public.payments where is_sandbox),\n    'live_payments', (select count(*) from public.payments where not is_sandbox));\nend $$;\n\n-- 開発・デモ用: サンドボックス利用額を付与（実決済ではない旨を記録）\ncreate or replace function public.admin_sandbox_credit_spend(p_user uuid, p_amount int, p_note text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  perform public.assert_sandbox();\n  if (select role from public.profiles where id = p_user) <> 'man' then perform public.raise_app('INVALID', '男性会員のみ対象です'); end if;\n  insert into public.payments (user_id, kind, amount, status, provider, is_sandbox, captured_at, note)\n    values (p_user, 'adjustment', p_amount, 'captured', 'sandbox', true, now(), coalesce(p_note, 'デモ用利用額'));\n  perform public.audit('admin.sandbox_credit', 'user', p_user::text, jsonb_build_object('amount', p_amount));\n  perform public.recompute_man(p_user, 'sandbox_credit');\n  return public.admin_get_user(p_user);\nend $$;\n\ncreate or replace function public.admin_expire_entitlement(p_user uuid) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  update public.membership_entitlements set status = 'expired', updated_at = now() where user_id = p_user and status = 'active';\n  perform public.audit('admin.expire_entitlement', 'user', p_user::text, '{}');\n  return public.admin_get_user(p_user);\nend $$;\n\n-- 期限切れサブスクの失効（pg_cron などから定期実行する想定）\ncreate or replace function public.expire_entitlements() returns int\nlanguage plpgsql security definer set search_path = public as $$\ndeclare n int;\nbegin\n  update public.membership_entitlements set status = 'expired', updated_at = now()\n    where status = 'active' and current_period_end <= now() and cancel_at_period_end;\n  get diagnostics n = row_count;\n  -- 自動更新（サンドボックスのみ。本番はストア/決済事業者の Webhook で更新）\n  update public.membership_entitlements set current_period_end = current_period_end + interval '30 days', updated_at = now()\n    where status = 'active' and current_period_end <= now() and not cancel_at_period_end and source = 'sandbox';\n  return n;\nend $$;\n"},{"name":"20261028000005_rls.sql","sql":"-- RLS と権限。クライアント(anon/authenticated)にはテーブルへの書き込み権限を一切与えない。\n-- 読み取りは本人・当事者・管理者に限定。書き込みはすべて検証付き RPC を経由する。\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['app_settings','profiles','women_profiles','men_profiles','venue_references','profile_photos',\n    'verification_states','availability_slots','membership_plans','membership_entitlements','rank_rules','rank_snapshots',\n    'applications','bookings','booking_events','conversations','messages','conversation_reads','payments','earnings_ledger',\n    'refunds','reports','blocks','inquiries','audit_events','notifications','share_links'] loop\n    execute format('alter table public.%I enable row level security', t);\n    execute format('revoke all on public.%I from anon, authenticated', t);\n  end loop;\nend $$;\n\n-- service_role / テーブル所有者は RLS をバイパスする（security definer 関数・Edge Functions の Webhook 処理用）\n-- 読み取り権限（行はポリシーで制限）\ngrant select on public.app_settings, public.membership_plans, public.rank_rules to anon, authenticated;\ngrant select on public.profiles, public.men_profiles, public.venue_references, public.profile_photos,\n  public.verification_states, public.availability_slots, public.membership_entitlements, public.rank_snapshots,\n  public.applications, public.bookings, public.booking_events, public.conversations, public.messages, public.conversation_reads,\n  public.payments, public.earnings_ledger, public.refunds, public.reports, public.blocks, public.inquiries,\n  public.audit_events, public.notifications, public.share_links to authenticated;\n-- 女性プロフィールは運営の非公開キュレーション列（review_score / review_note）を除外して付与\ngrant select (user_id, headline, bio, areas, plan_types, accept_mode, accept_requests, min_man_level, ng_note, is_published,\n  rank_code, rank_score, xp, level, updated_at) on public.women_profiles to authenticated;\n\ncreate policy settings_read on public.app_settings for select to anon, authenticated using (is_public or public.is_admin());\ncreate policy plans_read on public.membership_plans for select to anon, authenticated using (is_active or public.is_admin());\ncreate policy rank_rules_read on public.rank_rules for select to anon, authenticated using (true);\n\ncreate policy profiles_self on public.profiles for select to authenticated using (id = auth.uid() or public.is_admin());\ncreate policy women_self on public.women_profiles for select to authenticated using (user_id = auth.uid() or public.is_admin());\ncreate policy men_self on public.men_profiles for select to authenticated using (user_id = auth.uid() or public.is_admin());\ncreate policy venue_self on public.venue_references for select to authenticated using (woman_id = auth.uid() or public.is_admin());\ncreate policy photos_self on public.profile_photos for select to authenticated using (user_id = auth.uid() or public.is_admin());\ncreate policy verification_self on public.verification_states for select to authenticated using (user_id = auth.uid() or public.is_admin());\ncreate policy slots_self on public.availability_slots for select to authenticated using (woman_id = auth.uid() or public.is_admin());\ncreate policy entitlements_self on public.membership_entitlements for select to authenticated using (user_id = auth.uid() or public.is_admin());\ncreate policy snapshots_self on public.rank_snapshots for select to authenticated using (user_id = auth.uid() or public.is_admin());\n\ncreate policy applications_party on public.applications for select to authenticated\n  using (man_id = auth.uid() or woman_id = auth.uid() or public.is_admin());\ncreate policy bookings_party on public.bookings for select to authenticated\n  using (man_id = auth.uid() or woman_id = auth.uid() or public.is_admin());\ncreate policy booking_events_party on public.booking_events for select to authenticated\n  using (public.is_admin() or exists (select 1 from public.bookings b where b.id = booking_id and auth.uid() in (b.man_id, b.woman_id)));\n\n-- チャット: 当事者のみ。ブロック後は当事者も参照不可（Realtime の配信判定にも適用される）\ncreate policy conversations_party on public.conversations for select to authenticated\n  using ((auth.uid() in (man_id, woman_id) and not public.is_blocked_pair(man_id, woman_id)) or public.is_admin());\ncreate policy messages_party on public.messages for select to authenticated\n  using (exists (select 1 from public.conversations c where c.id = conversation_id\n                 and auth.uid() in (c.man_id, c.woman_id) and not public.is_blocked_pair(c.man_id, c.woman_id))\n         or public.is_admin());\ncreate policy reads_self on public.conversation_reads for select to authenticated using (user_id = auth.uid());\n\n-- お金: 本人と管理者のみ。女性は自分の台帳のみ（男性の支払額は見えない）\ncreate policy payments_self on public.payments for select to authenticated using (user_id = auth.uid() or public.is_admin());\ncreate policy earnings_self on public.earnings_ledger for select to authenticated using (woman_id = auth.uid() or public.is_admin());\ncreate policy refunds_self on public.refunds for select to authenticated using (requested_by = auth.uid() or public.is_admin());\n\ncreate policy reports_self on public.reports for select to authenticated using (reporter_id = auth.uid() or public.is_admin());\ncreate policy blocks_self on public.blocks for select to authenticated using (blocker_id = auth.uid() or public.is_admin());\ncreate policy inquiries_self on public.inquiries for select to authenticated using (user_id = auth.uid() or public.is_admin());\ncreate policy audit_admin on public.audit_events for select to authenticated using (public.is_admin());\ncreate policy notifications_self on public.notifications for select to authenticated using (user_id = auth.uid());\ncreate policy share_links_self on public.share_links for select to authenticated using (woman_id = auth.uid() or public.is_admin());\n\n-- ---------------------------------------------------------------- function execute privileges\n-- 既定では public スキーマの関数は誰でも実行できるため、一旦すべて剥奪してから公開 RPC のみ付与する。\nrevoke execute on all functions in schema public from public, anon, authenticated;\nalter default privileges in schema public revoke execute on functions from public, anon, authenticated;\n\n-- RLS ポリシー内で使う読み取り専用ヘルパー\ngrant execute on function public.is_admin(), public.my_role(), public.is_blocked_pair(uuid, uuid) to anon, authenticated;\n\ngrant execute on function public.get_public_settings(), public.get_share_link_preview(text) to anon, authenticated;\n\ngrant execute on function\n  public.get_me(), public.update_my_profile(text, text, text), public.submit_verification(int, boolean),\n  public.list_notifications(int), public.mark_notifications_read(),\n  public.search_women(text, text, date, boolean, text, int, int), public.get_woman_detail(uuid),\n  public.membership_overview(), public.sandbox_subscribe(text), public.cancel_subscription(), public.resume_subscription(),\n  public.submit_application(uuid, text), public.request_booking(uuid, text), public.redeem_share_link(text),\n  public.update_woman_profile(text, text, text, text, text[], text[], boolean),\n  public.set_accept_settings(public.accept_mode, boolean, int, text), public.upsert_venue(text, text, boolean), public.delete_venue(),\n  public.add_photo(text), public.delete_photo(uuid), public.make_photo_primary(uuid),\n  public.create_slot(timestamptz, timestamptz, text, text, int, text), public.list_my_slots(), public.close_slot(uuid),\n  public.list_incoming(), public.decide_application(uuid, boolean),\n  public.accept_booking(uuid), public.decline_booking(uuid, text), public.complete_booking(uuid), public.cancel_booking(uuid, text),\n  public.open_dispute(uuid, text), public.request_refund(uuid, text),\n  public.get_booking(uuid), public.list_my_bookings(text), public.woman_dashboard(), public.get_earnings(), public.get_share_link(boolean),\n  public.list_conversations(), public.get_messages(uuid, bigint), public.send_message(uuid, text),\n  public.block_user(uuid), public.unblock_user(uuid), public.list_blocks(),\n  public.report_user(uuid, text, text, uuid, bigint), public.submit_inquiry(text, text), public.list_my_inquiries(),\n  public.request_account_deletion(text),\n  -- 管理系（関数内で require_admin により検証）\n  public.admin_dashboard(), public.admin_list_users(text, text, text, text), public.admin_get_user(uuid),\n  public.admin_set_verification(uuid, public.verification_status, text), public.admin_set_user_status(uuid, public.account_status, text),\n  public.admin_set_review(uuid, int, text), public.admin_set_venue_status(uuid, public.verification_status), public.admin_review_queue(),\n  public.admin_moderate_photo(uuid, text), public.admin_list_settings(), public.admin_update_setting(text, jsonb),\n  public.admin_upsert_plan(text, text, int, text, jsonb, boolean, int), public.admin_upsert_rank_rule(text, text, text, numeric, int),\n  public.admin_list_bookings(text), public.admin_resolve_dispute(uuid, text, text), public.admin_list_refunds(text),\n  public.admin_decide_refund(uuid, boolean), public.admin_list_reports(text),\n  public.admin_update_report(uuid, public.report_status, text, boolean), public.admin_list_audit(int),\n  public.admin_list_inquiries(text), public.admin_reply_inquiry(uuid, text, text), public.admin_process_deletion(uuid),\n  public.admin_payment_status(), public.admin_sandbox_credit_spend(uuid, int, text), public.admin_expire_entitlement(uuid)\nto authenticated;\n"},{"name":"20261028000006_storage_realtime.sql","sql":"-- プロフィール写真: 非公開バケット + 署名付きURL。アップロードは自分のフォルダ（{uid}/...）のみ。\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues ('profile-photos', 'profile-photos', false, 5242880, array['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/svg+xml'])\non conflict (id) do nothing;\n\ncreate policy photos_upload_own on storage.objects for insert to authenticated\n  with check (bucket_id = 'profile-photos' and (storage.foldername(name))[1] = auth.uid()::text);\ncreate policy photos_delete_own on storage.objects for delete to authenticated\n  using (bucket_id = 'profile-photos' and (storage.foldername(name))[1] = auth.uid()::text);\n-- 閲覧（署名URLの発行）: 本人 / 公開承認済みの写真 / 管理者\n-- profile_photos 自体も RLS 下にあるため、判定は security definer 関数で行う\ncreate or replace function public.photo_is_viewable(p_path text) returns boolean\nlanguage sql stable security definer set search_path = public as $$\n  select exists (select 1 from public.profile_photos p join public.profiles u on u.id = p.user_id\n                 where p.storage_path = p_path and p.status = 'approved' and u.status = 'active'\n                   and not public.is_blocked_pair(p.user_id, auth.uid()))\n$$;\nrevoke execute on function public.photo_is_viewable(text) from public, anon;\ngrant execute on function public.photo_is_viewable(text) to authenticated;\n\ncreate policy photos_read on storage.objects for select to authenticated\n  using (bucket_id = 'profile-photos' and (\n    (storage.foldername(name))[1] = auth.uid()::text\n    or public.is_admin()\n    or public.photo_is_viewable(name)));\n\n-- Realtime: メッセージと通知の変更を購読（配信対象は上記 RLS の select ポリシーで制限される）\nalter publication supabase_realtime add table public.messages, public.notifications;\n"},{"name":"20261029000007_ux_kaizen.sql","sql":"-- UI/UX 改善に伴う表示用データの追加（ロジック・権限は既存のまま）\n--  * チャット: 相手との予約の状況・相手の既読位置\n--  * 女性ホーム: 収益を「確定 / 予定 / 保留」に分けて返す、今月の完了件数、最上位ランク判定\n--  * 管理ダッシュボード: 予約・決済・返金の状態別件数を同じ定義で返す\n\ncreate or replace function public.pair_booking(p_man uuid, p_woman uuid) returns jsonb\nlanguage sql stable security definer set search_path = public as $$\n  -- 表示優先度: 確定済みの予定 > 承認待ち > 申立て中 > 直近のもの\n  select jsonb_build_object('id', b.id, 'status', b.status, 'start_at', b.start_at, 'end_at', b.end_at)\n  from public.bookings b\n  where b.man_id = p_man and b.woman_id = p_woman\n  order by case b.status when 'accepted' then 0 when 'requested' then 1 when 'disputed' then 2 else 3 end,\n           case when b.status in ('accepted', 'requested') then b.start_at end asc nulls last,\n           b.created_at desc\n  limit 1\n$$;\nrevoke execute on function public.pair_booking(uuid, uuid) from public, anon, authenticated;\n\ncreate or replace function public.get_messages(p_conversation uuid, p_after bigint default 0) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_user(); c public.conversations; last_id bigint; other uuid;\nbegin\n  select * into c from public.conversations where id = p_conversation;\n  if not found or uid not in (c.man_id, c.woman_id) or public.is_blocked_pair(c.man_id, c.woman_id) then\n    perform public.raise_app('NOT_FOUND', 'メッセージが見つかりません');\n  end if;\n  other := case when c.man_id = uid then c.woman_id else c.man_id end;\n  select max(id) into last_id from public.messages where conversation_id = p_conversation;\n  if last_id is not null then\n    insert into public.conversation_reads (conversation_id, user_id, last_read_id) values (p_conversation, uid, last_id)\n      on conflict (conversation_id, user_id) do update set last_read_id = greatest(public.conversation_reads.last_read_id, excluded.last_read_id);\n  end if;\n  return jsonb_build_object(\n    'can_chat', public.can_chat(p_conversation, uid),\n    'counterpart', (select jsonb_build_object('id', o.id, 'display_name', o.display_name, 'role', o.role, 'photos', public.photo_paths(o.id))\n                    from public.profiles o where o.id = other),\n    'counterpart_read_id', coalesce((select last_read_id from public.conversation_reads where conversation_id = p_conversation and user_id = other), 0),\n    'booking', public.pair_booking(c.man_id, c.woman_id),\n    'messages', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'body', m.body, 'created_at', m.created_at, 'mine', m.sender_id = uid)\n                 order by m.id), '[]')\n                 from (select * from public.messages where conversation_id = p_conversation and id > coalesce(p_after, 0)\n                       order by id desc limit 200) m));\nend $$;\n\ncreate or replace function public.woman_dashboard() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare uid uuid := public.require_role('woman'); w public.women_profiles; nxt record; month_start timestamptz;\n  sb boolean := public.setting('payment_mode') #>> '{}' = 'sandbox'; fee numeric := public.setting_num('platform_fee_rate', 0.2);\n  top_sort int;\nbegin\n  select * into w from public.women_profiles where user_id = uid;\n  month_start := date_trunc('month', now() at time zone 'Asia/Tokyo') at time zone 'Asia/Tokyo';\n  select code, min_value into nxt from public.rank_rules where audience = 'woman' and min_value > w.rank_score order by min_value limit 1;\n  select max(sort) into top_sort from public.rank_rules where audience = 'woman';\n  return jsonb_build_object(\n    'pending_applications', (select count(*) from public.applications where woman_id = uid and status = 'pending'),\n    'pending_bookings', (select count(*) from public.bookings where woman_id = uid and status = 'requested'),\n    -- 確定: 完了して台帳に記録された報酬（返金の取消を含む）\n    'month_net', (select coalesce(sum(net), 0) from public.earnings_ledger where woman_id = uid and created_at >= month_start\n                  and entry_type in ('earning', 'reversal') and is_sandbox = sb),\n    'month_completed', (select count(*) from public.bookings where woman_id = uid and status = 'completed' and completed_at >= month_start),\n    'total_net', public.woman_earnings_net(uid),\n    -- 予定: 承認済み（予約確定）で未完了の予約の見込み額（手数料控除後）。まだ確定していない\n    'expected_net', (select coalesce(sum(price - round(price * fee)), 0)::int from public.bookings where woman_id = uid and status = 'accepted'),\n    'expected_count', (select count(*) from public.bookings where woman_id = uid and status = 'accepted'),\n    -- 保留: 申立て中の予約（運営の判断待ち）\n    'held_net', (select coalesce(sum(price - round(price * fee)), 0)::int from public.bookings where woman_id = uid and status = 'disputed'),\n    'held_count', (select count(*) from public.bookings where woman_id = uid and status = 'disputed'),\n    'is_sandbox', sb,\n    'upcoming', (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'start_at', b.start_at, 'end_at', b.end_at, 'area', b.area,\n                 'plan_type', b.plan_type, 'man_name', p.display_name) order by b.start_at), '[]')\n                 from public.bookings b join public.profiles p on p.id = b.man_id\n                 where b.woman_id = uid and b.status = 'accepted'),\n    'rank_code', w.rank_code, 'rank_score', w.rank_score,\n    'is_top_rank', public.rank_sort('woman', w.rank_code) >= coalesce(top_sort, 0),\n    'next_rank', case when nxt.code is not null then jsonb_build_object('code', nxt.code, 'min_value', nxt.min_value) end,\n    'rank_floor', (select min_value from public.rank_rules where audience = 'woman' and code = w.rank_code),\n    'rank_breakdown', (select breakdown - 'weights' from public.rank_snapshots where user_id = uid and audience = 'woman' order by computed_at desc limit 1),\n    'level', w.level, 'xp', w.xp, 'level_floor_xp', public.xp_for_level(w.level), 'next_level_xp', public.xp_for_level(w.level + 1),\n    'completed', public.completed_count(uid),\n    'is_published', w.is_published, 'accept_mode', w.accept_mode, 'accept_requests', w.accept_requests,\n    'badges', public.badges(uid));\nend $$;\n\ncreate or replace function public.admin_dashboard() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare decided int; ok int; sb boolean := public.setting('payment_mode') #>> '{}' = 'sandbox';\nbegin\n  perform public.require_admin();\n  -- 成立率 = (予約確定 + 完了) ÷ 女性が判断済みの申込（確定・完了・不成立・申立て）。申込者による取り下げ・キャンセルは分母から除外\n  select count(*) filter (where status in ('accepted', 'completed', 'declined', 'disputed')),\n         count(*) filter (where status in ('accepted', 'completed', 'disputed'))\n    into decided, ok from public.bookings;\n  return jsonb_build_object(\n    'users', (select jsonb_build_object(\n       'total', count(*) filter (where role <> 'admin'),\n       'women', count(*) filter (where role = 'woman'), 'men', count(*) filter (where role = 'man'),\n       'suspended', count(*) filter (where status = 'suspended'),\n       'deletion_requested', count(*) filter (where status = 'deletion_requested'),\n       'new_7d', count(*) filter (where role <> 'admin' and created_at > now() - interval '7 days')) from public.profiles),\n    'verification_pending', (select count(*) from public.verification_states where status = 'pending'),\n    'venue_pending', (select count(*) from public.venue_references where verify_status = 'pending'),\n    'photos_pending', (select count(*) from public.profile_photos where status = 'pending'),\n    'applications', (select jsonb_build_object('total', count(*), 'pending', count(*) filter (where status = 'pending'),\n                     'approved', count(*) filter (where status = 'approved')) from public.applications),\n    'bookings', (select jsonb_build_object(\n       'requested', count(*) filter (where status = 'requested'), 'accepted', count(*) filter (where status = 'accepted'),\n       'completed', count(*) filter (where status = 'completed'), 'declined', count(*) filter (where status = 'declined'),\n       'canceled', count(*) filter (where status = 'canceled'), 'disputed', count(*) filter (where status = 'disputed')) from public.bookings),\n    'booking_total', (select count(*) from public.bookings),\n    'success_rate', case when decided > 0 then round(ok::numeric / decided * 100, 1) else null end,\n    'payments', (select jsonb_build_object(\n       'authorized', count(*) filter (where status = 'authorized'), 'captured', count(*) filter (where status = 'captured'),\n       'voided', count(*) filter (where status = 'voided'), 'refunded', count(*) filter (where status = 'refunded'))\n       from public.payments where is_sandbox = sb),\n    'revenue', (select jsonb_build_object(\n       'subscription', coalesce(sum(amount) filter (where kind = 'subscription' and status = 'captured'), 0),\n       'booking_gross', coalesce(sum(amount) filter (where kind = 'booking' and status in ('captured', 'refunded')), 0),\n       'refunded', coalesce((select sum(r.amount) from public.refunds r join public.payments p2 on p2.id = r.payment_id\n                             where r.status = 'processed' and p2.is_sandbox = sb), 0))\n       from public.payments where is_sandbox = sb),\n    'platform_fee', (select coalesce(sum(fee), 0) from public.earnings_ledger where is_sandbox = sb),\n    'reports_open', (select count(*) from public.reports where status in ('open', 'reviewing')),\n    'disputes_open', (select count(*) from public.bookings where status = 'disputed'),\n    'refunds_open', (select count(*) from public.refunds where status = 'requested'),\n    'inquiries_open', (select count(*) from public.inquiries where status = 'open'),\n    'is_sandbox', sb,\n    'payment_mode', public.setting('payment_mode'));\nend $$;\n"}];
export const SEED = "-- デモ/開発環境専用シード。本番環境では実行しないこと。\n-- パスワードはすべて DemoPass123! （デモ用）。写真は自作イラストと AI 生成のデモ写真（実在人物ではない・「DEMO・AI生成」表記入り）（seed-assets/demo/*.svg）。\n\nupdate public.app_settings set value = 'true' where key = 'demo_mode';\n\ncreate or replace function pg_temp.demo_user(p_id uuid, p_email text, p_role text, p_name text) returns void\nlanguage plpgsql as $$\nbegin\n  insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,\n    raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change)\n  values ('00000000-0000-0000-0000-000000000000', p_id, 'authenticated', 'authenticated', p_email,\n    extensions.crypt('DemoPass123!', extensions.gen_salt('bf')), now(),\n    '{\"provider\":\"email\",\"providers\":[\"email\"]}', jsonb_build_object('role', p_role, 'display_name', p_name),\n    now() - interval '60 days', now(), '', '', '', '');\n  insert into auth.identities (id, provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)\n  values (gen_random_uuid(), p_id::text, p_id, jsonb_build_object('sub', p_id::text, 'email', p_email), 'email', now(), now(), now());\n  update public.verification_states set status = 'approved', method = 'demo', birth_year = 1995, submitted_at = now(), reviewed_at = now()\n    where user_id = p_id;\nend $$;\n\n-- ---------------------------------------------------------------- users\nselect pg_temp.demo_user('a0000000-0000-4000-8000-000000000001', 'admin@demo.projectgold.local', 'man', '運営デモ');\nupdate public.profiles set role = 'admin' where id = 'a0000000-0000-4000-8000-000000000001';\ndelete from public.men_profiles where user_id = 'a0000000-0000-4000-8000-000000000001';\n\nselect pg_temp.demo_user('b0000000-0000-4000-8000-000000000001', 'misaki@demo.projectgold.local', 'woman', '美咲');\nselect pg_temp.demo_user('b0000000-0000-4000-8000-000000000002', 'rena@demo.projectgold.local', 'woman', '玲奈');\nselect pg_temp.demo_user('b0000000-0000-4000-8000-000000000003', 'sakura@demo.projectgold.local', 'woman', 'さくら');\nselect pg_temp.demo_user('b0000000-0000-4000-8000-000000000004', 'hinano@demo.projectgold.local', 'woman', 'ひなの');\nselect pg_temp.demo_user('b0000000-0000-4000-8000-000000000005', 'yui@demo.projectgold.local', 'woman', 'ゆい');\nselect pg_temp.demo_user('b0000000-0000-4000-8000-000000000006', 'akari@demo.projectgold.local', 'woman', 'あかり');\n\nselect pg_temp.demo_user('c0000000-0000-4000-8000-000000000001', 'taro@demo.projectgold.local', 'man', '太郎');\nselect pg_temp.demo_user('c0000000-0000-4000-8000-000000000002', 'kenichi@demo.projectgold.local', 'man', '健一');\nselect pg_temp.demo_user('c0000000-0000-4000-8000-000000000003', 'regular@demo.projectgold.local', 'man', '常連デモ');\n\n-- ---------------------------------------------------------------- women profiles\nupdate public.profiles p set area = v.area from (values\n  ('b0000000-0000-4000-8000-000000000001'::uuid, '銀座'), ('b0000000-0000-4000-8000-000000000002'::uuid, '六本木'),\n  ('b0000000-0000-4000-8000-000000000003'::uuid, '新宿'), ('b0000000-0000-4000-8000-000000000004'::uuid, '渋谷'),\n  ('b0000000-0000-4000-8000-000000000005'::uuid, '恵比寿'), ('b0000000-0000-4000-8000-000000000006'::uuid, '銀座')) v(id, area)\nwhere p.id = v.id;\n\nupdate public.women_profiles w set headline = v.headline, bio = v.bio, areas = v.areas, plan_types = v.plans,\n  accept_mode = v.mode::public.accept_mode, review_score = v.review, is_published = true\nfrom (values\n  ('b0000000-0000-4000-8000-000000000001'::uuid, '静かなラウンジで、ゆっくりお話を', '銀座で働いて5年目です。ワインと美術館めぐりが好きで、落ち着いた会話を大切にしています。お食事でもカフェでも、心地よい時間をご一緒できたら嬉しいです。', '{銀座,日本橋}'::text[], '{食事,カフェ,バー同席}'::text[], 'select', 92),\n  ('b0000000-0000-4000-8000-000000000002'::uuid, '笑顔とおいしいお店が好きです', '六本木在住。話題のレストランを開拓するのが趣味です。お仕事のお話や旅行の話を聞くのが大好きなので、気軽に声をかけてください。', '{六本木,麻布十番}', '{食事,バー同席}', 'select', 85),\n  ('b0000000-0000-4000-8000-000000000003'::uuid, 'カフェ巡りとお散歩が好き', '新宿エリア中心です。カフェでのんびりお話しするのが好きです。映画や音楽の話ができたら嬉しいです。初めての方も歓迎です。', '{新宿,代々木}', '{カフェ,食事}', 'open', 75),\n  ('b0000000-0000-4000-8000-000000000004'::uuid, '和食とお酒の話ならおまかせ', '渋谷・表参道あたりでお会いできます。日本酒と和食が好きで、おすすめのお店をご紹介できます。気軽にお申し込みください。', '{渋谷,表参道}', '{食事,バー同席}', 'open', 60),\n  ('b0000000-0000-4000-8000-000000000005'::uuid, 'はじめまして、ゆいです', '恵比寿で働いています。まだ始めたばかりですが、楽しい時間をご一緒できるようにがんばります。甘いものが好きです。', '{恵比寿}', '{カフェ,食事}', 'open', 50),\n  ('b0000000-0000-4000-8000-000000000006'::uuid, 'ゆっくりお話ししましょう', '銀座のお店に勤めています。読書と紅茶が好き。落ち着いた雰囲気のカフェでお話しするのが理想です。', '{銀座}', '{カフェ}', 'select', 40)\n) v(id, headline, bio, areas, plans, mode, review)\nwhere w.user_id = v.id;\n\ninsert into public.venue_references (woman_id, venue_name, area, is_public, verify_status, verified_at) values\n  ('b0000000-0000-4000-8000-000000000001', 'Lounge Aurum（デモ店舗）', '銀座', true, 'approved', now()),\n  ('b0000000-0000-4000-8000-000000000002', 'Club Lumière（デモ店舗）', '六本木', true, 'approved', now()),\n  ('b0000000-0000-4000-8000-000000000003', 'Bar Sakura（デモ店舗）', '新宿', false, 'pending', null),\n  ('b0000000-0000-4000-8000-000000000004', 'Salon Hinoki（デモ店舗）', '渋谷', false, 'approved', now());\n\ninsert into public.profile_photos (user_id, storage_path, sort_order, status)\nselect ('b0000000-0000-4000-8000-00000000000' || w)::uuid, format('demo/w%s-%s.svg', w, n), n - 1, 'approved'\nfrom generate_series(1, 6) w, generate_series(1, 3) n;\ninsert into public.profile_photos (user_id, storage_path, sort_order, status) values\n  ('c0000000-0000-4000-8000-000000000001', 'demo/m1-1.svg', 0, 'approved'),\n  ('c0000000-0000-4000-8000-000000000002', 'demo/m2-1.svg', 0, 'approved');\n\nupdate public.men_profiles set bio = '都内で会社を経営しています。おいしいお店でゆっくり話すのが好きです。' where user_id = 'c0000000-0000-4000-8000-000000000001';\nupdate public.men_profiles set bio = '外資系勤務。ワインと旅行が趣味です。よろしくお願いします。' where user_id = 'c0000000-0000-4000-8000-000000000002';\nupdate public.profiles set area = '港区' where id in ('c0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000002');\n\n-- 健一: GOLD プラン（サンドボックス）\ninsert into public.payments (id, user_id, kind, plan_code, amount, status, provider, is_sandbox, captured_at, note)\nvalues ('d0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000002', 'subscription', 'GOLD', 14800, 'captured', 'sandbox', true, now(), 'デモ');\ninsert into public.membership_entitlements (user_id, plan_code, current_period_end, source, external_ref)\nvalues ('c0000000-0000-4000-8000-000000000002', 'GOLD', now() + interval '30 days', 'sandbox', 'd0000000-0000-4000-8000-000000000001');\n\n-- ---------------------------------------------------------------- past history（アプリ内実績のデモ）\ncreate or replace function pg_temp.demo_history(p_woman uuid, p_man uuid, p_count int, p_price int) returns void\nlanguage plpgsql as $$\ndeclare i int; b uuid; pay uuid; fee int := round(p_price * 0.2);\nbegin\n  for i in 1..p_count loop\n    insert into public.bookings (man_id, woman_id, start_at, end_at, area, plan_type, price, status, accepted_at, completed_at, created_at)\n      values (p_man, p_woman, now() - make_interval(days => 3 + i * 3, hours => 2), now() - make_interval(days => 3 + i * 3),\n              '銀座', '食事', p_price, 'completed', now() - make_interval(days => 5 + i * 3), now() - make_interval(days => 3 + i * 3),\n              now() - make_interval(days => 6 + i * 3))\n      returning id into b;\n    insert into public.booking_events (booking_id, from_status, to_status, actor_id, note) values\n      (b, null, 'requested', p_man, 'seed'), (b, 'requested', 'accepted', p_woman, 'seed'), (b, 'accepted', 'completed', p_woman, 'seed');\n    insert into public.payments (user_id, kind, booking_id, amount, status, provider, is_sandbox, captured_at, note)\n      values (p_man, 'booking', b, p_price, 'captured', 'sandbox', true, now() - make_interval(days => 3 + i * 3), 'デモ実績') returning id into pay;\n    insert into public.earnings_ledger (woman_id, booking_id, payment_id, entry_type, gross, fee, net, is_sandbox, created_at)\n      values (p_woman, b, pay, 'earning', p_price, fee, p_price - fee, true, now() - make_interval(days => 3 + i * 3));\n  end loop;\n  insert into public.conversations (man_id, woman_id) values (p_man, p_woman) on conflict do nothing;\nend $$;\n\nselect pg_temp.demo_history('b0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000003', 12, 30000);\nselect pg_temp.demo_history('b0000000-0000-4000-8000-000000000002', 'c0000000-0000-4000-8000-000000000003', 4, 25000);\ninsert into public.applications (man_id, woman_id, status, source, decided_at) values\n  ('c0000000-0000-4000-8000-000000000003', 'b0000000-0000-4000-8000-000000000001', 'approved', 'invite', now() - interval '50 days'),\n  ('c0000000-0000-4000-8000-000000000003', 'b0000000-0000-4000-8000-000000000002', 'approved', 'request', now() - interval '20 days');\ninsert into public.messages (conversation_id, sender_id, body, created_at)\nselect c.id, c.woman_id, '先日はありがとうございました。またお話しできるのを楽しみにしています。', now() - interval '3 days'\nfrom public.conversations c where c.man_id = 'c0000000-0000-4000-8000-000000000003';\nupdate public.conversations set last_message_at = now() - interval '3 days' where man_id = 'c0000000-0000-4000-8000-000000000003';\n\n-- ---------------------------------------------------------------- upcoming slots (JST 19:00-21:00 / 15:00-16:30)\ninsert into public.availability_slots (woman_id, start_at, end_at, area, plan_type, price, note)\nselect w.id, (((date_trunc('day', now() at time zone 'Asia/Tokyo') + make_interval(days => k)) + time '19:00') at time zone 'Asia/Tokyo'),\n  (((date_trunc('day', now() at time zone 'Asia/Tokyo') + make_interval(days => k)) + time '21:00') at time zone 'Asia/Tokyo'),\n  w.area, w.plan, w.price, '仮の料金設定（デモ）'\nfrom (values\n  ('b0000000-0000-4000-8000-000000000001'::uuid, '銀座', '食事', 40000),\n  ('b0000000-0000-4000-8000-000000000002'::uuid, '六本木', '食事', 32000),\n  ('b0000000-0000-4000-8000-000000000003'::uuid, '新宿', '食事', 22000),\n  ('b0000000-0000-4000-8000-000000000004'::uuid, '渋谷', 'バー同席', 22000),\n  ('b0000000-0000-4000-8000-000000000005'::uuid, '恵比寿', '食事', 15000),\n  ('b0000000-0000-4000-8000-000000000006'::uuid, '銀座', 'カフェ', 15000)) w(id, area, plan, price),\n  generate_series(1, 9, 2) k;\n\ninsert into public.availability_slots (woman_id, start_at, end_at, area, plan_type, price, note)\nselect w.id, (((date_trunc('day', now() at time zone 'Asia/Tokyo') + make_interval(days => k)) + time '15:00') at time zone 'Asia/Tokyo'),\n  (((date_trunc('day', now() at time zone 'Asia/Tokyo') + make_interval(days => k)) + time '16:30') at time zone 'Asia/Tokyo'),\n  w.area, 'カフェ', w.price, 'カフェでのお茶（デモ）'\nfrom (values ('b0000000-0000-4000-8000-000000000003'::uuid, '新宿', 12000), ('b0000000-0000-4000-8000-000000000005'::uuid, '恵比寿', 9000),\n             ('b0000000-0000-4000-8000-000000000006'::uuid, '銀座', 9000)) w(id, area, price),\n  generate_series(2, 6, 2) k;\n\n-- ---------------------------------------------------------------- compute ranks & levels\nselect public.recompute_user(id, 'seed') from public.profiles where role in ('woman', 'man');\n";
